INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0132-a04-008-4', 'p0132', 'sanguozhi', 'a04-008', '《三國志·魏書八》', '典略曰：黑山、黃巾諸帥，本非冠蓋，自相號字，謂騎白馬者為張白騎，謂輕捷者為張飛燕，謂聲大者為張雷公，其饒鬚者則自稱于羝根，其眼大者自稱李大目。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0132-a04-009-5', 'p0132', 'sanguozhi', 'a04-009', '《三國志·魏書九》', '初，建安五年，時霸從妹年十三四，在本郡，出行樵採，為張飛所得。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0132-a04-009-6', 'p0132', 'sanguozhi', 'a04-009', '《三國志·魏書九》', '備遣張飛屯固山，欲斷軍後。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0132-a04-014-7', 'p0132', 'sanguozhi', 'a04-014', '《三國志·魏書十四》', '劉備有英名，關羽、張飛皆萬人敵也，權必資之以禦我。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0132-a04-014-8', 'p0132', 'sanguozhi', 'a04-014', '《三國志·魏書十四》', '張飛、關羽者，皆萬人之敵也，為之死用。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0132-a04-014-9', 'p0132', 'sanguozhi', 'a04-014', '《三國志·魏書十四》', '太祖令劉備拒袁術，昭曰：「備勇而志大，關羽、張飛為之羽翼，恐備之心未可得論也！');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0132-a04-014-10', 'p0132', 'sanguozhi', 'a04-014', '《三國志·魏書十四》', '若小緩之，諸葛亮明於治而為相，關羽、張飛勇冠三軍而為將，蜀民旣定，據險守要，則不可犯矣。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0132-a04-017-11', 'p0132', 'sanguozhi', 'a04-017', '《三國志·魏書十七》', '進軍宕渠，為備將張飛所拒，引還南鄭。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0132-a04-025-12', 'p0132', 'sanguozhi', 'a04-025', '《三國志·魏書二十五》', '會劉備遣張飛、馬超等從沮道趣下辯，而氐雷定等七部萬餘落反應之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0132-a04-032-13', 'p0132', 'sanguozhi', 'a04-032', '《三國志·蜀書二》', '英雄記曰：備留張飛守下邳，引兵與袁術戰於淮陰石亭，更有勝負。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0132-a04-032-14', 'p0132', 'sanguozhi', 'a04-032', '《三國志·蜀書二》', '陶謙故將曹豹在下邳，張飛欲殺之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0132-a04-032-15', 'p0132', 'sanguozhi', 'a04-032', '《三國志·蜀書二》', '旣去，備謂張飛、關羽曰：「吾豈種菜者乎？');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0132-a04-032-16', 'p0132', 'sanguozhi', 'a04-032', '《三國志·蜀書二》', '先主棄妻子，與諸葛亮、張飛、趙雲等數十騎走，曹公大獲其人衆輜重。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0132-a04-032-17', 'p0132', 'sanguozhi', 'a04-032', '《三國志·蜀書二》', '」備謂關羽、張飛曰：「彼欲致我，我今自結託於東而不往，非同盟之意也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0132-a04-032-18', 'p0132', 'sanguozhi', 'a04-032', '《三國志·蜀書二》', '」使關羽屯江陵，張飛屯秭歸，諸葛亮據南郡，備自住潺陵。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0132-a04-032-19', 'p0132', 'sanguozhi', 'a04-032', '《三國志·蜀書二》', '先主軍益彊，分遣諸將平下屬縣，諸葛亮、張飛、趙雲等將兵泝流定白帝、江州、江陽，惟關羽留鎮荊州。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0132-a04-032-20', 'p0132', 'sanguozhi', 'a04-032', '《三國志·蜀書二》', '諸葛亮達治知變，正而有謀，而為之相；張飛、關羽勇而有義，皆萬人之敵，而為之將：此三人者，皆人傑也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0132-a04-032-21', 'p0132', 'sanguozhi', 'a04-032', '《三國志·蜀書二》', '先主復領益州牧，諸葛亮為股肱，法正為謀主，關羽、張飛、馬超為爪牙，許靖、麋笁、簡雍為賔友。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0132-a04-032-22', 'p0132', 'sanguozhi', 'a04-032', '《三國志·蜀書二》', '先主令張飛進兵宕渠，與郃等戰於瓦口，破郃等，郃收兵還南鄭。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0132-a04-032-23', 'p0132', 'sanguozhi', 'a04-032', '《三國志·蜀書二》', '軍師將軍臣諸葛亮、盪寇將軍漢壽亭侯臣關羽、征虜將軍新亭侯臣張飛、征西將軍臣黃忠、鎮遠將軍臣賴恭、揚武將軍臣法正、興業將軍臣李嚴等一百二十人上言曰：昔唐堯至聖而四凶在朝，周成仁賢而四國作難，高后稱制而諸呂竊命，孝昭幼冲而上官逆謀，皆馮世寵，藉履國權，窮凶極亂，社稷幾危。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0132-a04-032-24', 'p0132', 'sanguozhi', 'a04-032', '《三國志·蜀書二》', '車騎將軍張飛為其左右所害。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0132-a04-033-25', 'p0132', 'sanguozhi', 'a04-033', '《三國志·蜀書三》', '三年秋九月，追謚故將軍關羽、張飛、馬超、龐統、黃忠。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0132-a04-034-26', 'p0132', 'sanguozhi', 'a04-034', '《三國志·蜀書四》', '後主敬哀皇后，車騎將軍張飛長女也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0132-a04-035-27', 'p0132', 'sanguozhi', 'a04-035', '《三國志·蜀書五》', '關羽、張飛等不恱，先主解之曰：「孤之有孔明，猶魚之有水也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0132-a04-035-28', 'p0132', 'sanguozhi', 'a04-035', '《三國志·蜀書五》', '先主自葭萌還攻璋，亮與張飛、趙雲等率衆泝江，分定郡縣，與先主共圍成都。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0132-a04-035-29', 'p0132', 'sanguozhi', 'a04-035', '《三國志·蜀書五》', '張飛卒後，領司隷校尉。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0132-a04-035-30', 'p0132', 'sanguozhi', 'a04-035', '《三國志·蜀書五》', '袁子曰：或問諸葛亮何如人也，袁子曰：張飛、關羽與劉備俱起，爪牙腹心之臣，而武人也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0132-a04-036-31', 'p0132', 'sanguozhi', 'a04-036', '《三國志·蜀書六》', '先主於鄉里合徒衆，而羽與張飛為之禦侮。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0132-a04-036-32', 'p0132', 'sanguozhi', 'a04-036', '《三國志·蜀書六》', '張飛字益德，涿郡人也，少與關羽俱事先主。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0132-a04-036-33', 'p0132', 'sanguozhi', 'a04-036', '《三國志·蜀書六》', '」張飛曰：「如是，當示之以禮。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0132-a04-036-34', 'p0132', 'sanguozhi', 'a04-036', '《三國志·蜀書六》', '為呼人主字，幾為關羽、張飛所殺。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0132-a04-036-35', 'p0132', 'sanguozhi', 'a04-036', '《三國志·蜀書六》', '權聞備西征，大遣舟船迎妹，而夫人內欲將後主還吳，雲與張飛勒兵截江，乃得後主還。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0132-a04-036-36', 'p0132', 'sanguozhi', 'a04-036', '《三國志·蜀書六》', '亮率雲與張飛等俱泝江西上，平定郡縣。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0132-a04-036-37', 'p0132', 'sanguozhi', 'a04-036', '《三國志·蜀書六》', '初，先主時，惟法正見謚；後主時，諸葛亮功德蓋世，蔣琬、費禕荷國之重，亦見謚；陳祗寵待，特加殊獎，夏侯霸遠來歸國，故復得謚；於是關羽、張飛、馬超、龐統、黃忠及雲乃追謚，時論以為榮。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0132-a04-036-38', 'p0132', 'sanguozhi', 'a04-036', '《三國志·蜀書六》', '評曰：關羽、張飛皆稱萬人之敵，為世虎臣。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0132-a04-039-39', 'p0132', 'sanguozhi', 'a04-039', '《三國志·蜀書九》', '零陵先賢傳曰：張飛甞就巴宿，巴不與語，飛遂忿恚。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0132-a04-039-40', 'p0132', 'sanguozhi', 'a04-039', '《三國志·蜀書九》', '諸葛亮謂巴曰：「張飛雖實武人，敬慕足下。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0132-a04-039-41', 'p0132', 'sanguozhi', 'a04-039', '《三國志·蜀書九》', '零陵先賢傳曰：輔吳將軍張昭甞對孫權論巴褊阨，不當拒張飛太甚。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0132-a04-040-42', 'p0132', 'sanguozhi', 'a04-040', '《三國志·蜀書十》', '及先主入蜀，自葭萌還攻劉璋，時封年二十餘，有武藝，氣力過人，將兵俱與諸葛亮、張飛等泝流西上，所在戰克。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0132-a04-040-43', 'p0132', 'sanguozhi', 'a04-040', '《三國志·蜀書十》', '先主為漢中王，遷治成都，當得重將以鎮漢川，衆論以為必在張飛，飛亦以心自許。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0132-a04-041-44', 'p0132', 'sanguozhi', 'a04-041', '《三國志·蜀書十一》', '張飛自荊州由墊江入，璋授裔兵，拒張飛於德陽陌下，軍敗，還成都。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0132-a04-054-45', 'p0132', 'sanguozhi', 'a04-054', '《三國志·吳書九》', '備詣京見權，瑜上疏曰：「劉備以梟雄之姿，而有關羽、張飛熊虎之將，必非乆屈為人用者。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0133-a04-032-0', 'p0133', 'sanguozhi', 'a04-032', '《三國志·蜀書二》', '先主棄妻子，與諸葛亮、張飛、趙雲等數十騎走，曹公大獲其人衆輜重。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0133-a04-032-1', 'p0133', 'sanguozhi', 'a04-032', '《三國志·蜀書二》', '先主軍益彊，分遣諸將平下屬縣，諸葛亮、張飛、趙雲等將兵泝流定白帝、江州、江陽，惟關羽留鎮荊州。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0133-a04-033-2', 'p0133', 'sanguozhi', 'a04-033', '《三國志·蜀書三》', '十三年敗於長阪，備棄妻子走，趙雲傳曰「雲身抱弱子以免」，即後主也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0133-a04-033-3', 'p0133', 'sanguozhi', 'a04-033', '《三國志·蜀書三》', '四年春三月，追謚故將軍趙雲。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0133-a04-034-4', 'p0133', 'sanguozhi', 'a04-034', '《三國志·蜀書四》', '值曹公軍至，追及先主於當陽長阪，于時困偪，棄后及後主，賴趙雲保護，得免於難。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0133-a04-034-5', 'p0133', 'sanguozhi', 'a04-034', '《三國志·蜀書四》', '夫人欲將太子歸吳，諸葛亮使趙雲勒兵斷江留太子，乃得止。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0133-a04-035-6', 'p0133', 'sanguozhi', 'a04-035', '《三國志·蜀書五》', '先主自葭萌還攻璋，亮與張飛、趙雲等率衆泝江，分定郡縣，與先主共圍成都。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0133-a04-035-7', 'p0133', 'sanguozhi', 'a04-035', '《三國志·蜀書五》', '六年春，揚聲由斜谷道取郿，使趙雲、鄧芝為疑軍，據箕谷，魏大將軍曹真舉衆拒之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0133-a04-035-8', 'p0133', 'sanguozhi', 'a04-035', '《三國志·蜀書五》', '自臣到漢中，中間朞年耳，然喪趙雲、陽羣、馬玉、閻芝、丁立、白壽、劉郃、鄧銅等及曲長屯將七十餘人，突將無前。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0133-a04-036-9', 'p0133', 'sanguozhi', 'a04-036', '《三國志·蜀書六》', '趙雲字子龍，常山真定人也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0133-a04-036-10', 'p0133', 'sanguozhi', 'a04-036', '《三國志·蜀書六》', '黃忠、趙雲彊摯壯猛，並作爪牙，其灌、滕之徒歟？');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0133-a04-045-11', 'p0133', 'sanguozhi', 'a04-045', '《三國志·蜀書十五》', '自豫州隨先主，名位常亞趙雲，俱以忠勇稱。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0133-a05-012-12', 'p0133', 'jinshu', 'a05-012', '《晉書·卷十二》', '韓雲如布，趙雲如牛，楚雲如日，宋雲如車，魯雲如馬，衞雲如犬，周雲如車輪，秦雲如行人，魏雲如鼠，鄭雲如絳衣，越雲如龍，蜀雲如囷。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0134-a03-009-0', 'p0134', 'houhanshu', 'a03-009', '《後漢書·卷九》', '十六年秋九月庚戌，曹操與韓遂、馬超戰於渭南，遂等大敗，關西平。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0134-a03-009-1', 'p0134', 'houhanshu', 'a03-009', '《後漢書·卷九》', '八月，馬超破涼州，殺刺史韋康。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0134-a03-069-2', 'p0134', 'houhanshu', 'a03-069', '《後漢書·卷六十九》', '從征馬超，為流矢所中死。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0134-a03-070-3', 'p0134', 'houhanshu', 'a03-070', '《後漢書·卷七十》', '後為馬超所圍，堅守歷時，救軍不至，遂為超所殺。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0134-a03-072-4', 'p0134', 'houhanshu', 'a03-072', '《後漢書·卷七十二》', '馬超率萬餘人攻兾城，阜率國士大夫及宗族子弟勝兵者千餘人，使弟岳於城上作偃月營，與超接戰。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0134-a03-075-5', 'p0134', 'houhanshu', 'a03-075', '《後漢書·卷七十五》', '韓遂、馬超之亂，關西民奔魯者數萬家。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0134-a04-001-6', 'p0134', 'sanguozhi', 'a04-001', '《三國志·魏書一》', '是時關中諸將疑繇欲自襲，馬超遂與韓遂、楊秋、李堪、成宜等叛。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0134-a04-001-7', 'p0134', 'sanguozhi', 'a04-001', '《三國志·魏書一》', '馬超餘衆梁興等屯藍田，使夏侯淵擊平之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0134-a04-001-8', 'p0134', 'sanguozhi', 'a04-001', '《三國志·魏書一》', '馬超、成宜，同惡相濟，濵據河、潼，求逞所欲，殄之渭南，獻馘萬計，遂定邊境，撫和戎狄，此又君之功也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0134-a04-001-9', 'p0134', 'sanguozhi', 'a04-001', '《三國志·魏書一》', '馬超在漢陽，復因羌、胡為害，氐王千萬叛應超，屯興國。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0134-a04-001-10', 'p0134', 'sanguozhi', 'a04-001', '《三國志·魏書一》', '劉備遣張飛、馬超、吳蘭等屯下辯；遣曹洪拒之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0134-a04-001-11', 'p0134', 'sanguozhi', 'a04-001', '《三國志·魏書一》', '三月，張飛、馬超走漢中，陰平氐強端斬吳蘭，傳其首。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0134-a04-008-12', 'p0134', 'sanguozhi', 'a04-008', '《三國志·魏書八》', '韓遂、馬超之亂，關西民從子午谷奔之者數萬家。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0134-a04-008-13', 'p0134', 'sanguozhi', 'a04-008', '《三國志·魏書八》', '馬超等反，不肯從，超破之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0134-a04-008-14', 'p0134', 'sanguozhi', 'a04-008', '《三國志·魏書八》', '建安十六年，並與馬超合。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0134-a04-009-15', 'p0134', 'sanguozhi', 'a04-009', '《三國志·魏書九》', '馬超圍涼州刺史韋康於兾，淵救康，未到，康敗。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0134-a04-009-16', 'p0134', 'sanguozhi', 'a04-009', '《三國志·魏書九》', '氐王千萬逃奔馬超，餘衆降。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0134-a04-009-17', 'p0134', 'sanguozhi', 'a04-009', '《三國志·魏書九》', '太祖討馬超，以仁行安西將軍，督諸將拒潼關，破超渭南。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0134-a04-010-18', 'p0134', 'sanguozhi', 'a04-010', '《三國志·魏書十》', '後為馬超所圍，堅守歷時，救軍不至，遂為超所殺。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0134-a04-010-19', 'p0134', 'sanguozhi', 'a04-010', '《三國志·魏書十》', '」彧曰：「關中將帥以十數，莫能相一，唯韓遂、馬超最彊。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0134-a04-010-20', 'p0134', 'sanguozhi', 'a04-010', '《三國志·魏書十》', '太祖後與韓遂、馬超戰於渭南，超等索割地以和，并求任子。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0134-a04-011-21', 'p0134', 'sanguozhi', 'a04-011', '《三國志·魏書十一》', '建安十六年，百姓聞馬超叛，避兵入山者千餘家，飢乏，漸相劫略，昭常遜辭以解之，是以寇難消息，衆咸宗焉。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0134-a04-012-22', 'p0134', 'sanguozhi', 'a04-012', '《三國志·魏書十二》', '」從破馬超等，子伯功為多。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0134-a04-012-23', 'p0134', 'sanguozhi', 'a04-012', '《三國志·魏書十二》', '太祖為司空，辟為掾屬，從西征馬超。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0134-a04-013-24', 'p0134', 'sanguozhi', 'a04-013', '《三國志·卷十三‧魏書十三》', '後馬超反，超劫洪，將詣華陰，使作露布。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0134-a04-014-25', 'p0134', 'sanguozhi', 'a04-014', '《三國志·魏書十四》', '魏書曰：太祖征馬超，文帝留守，使昱參軍事。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0134-a04-015-26', 'p0134', 'sanguozhi', 'a04-015', '《三國志·魏書十五》', '會約西討張猛，留行守舊營，而馬超等結反謀，舉約為都督。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0134-a04-015-27', 'p0134', 'sanguozhi', 'a04-015', '《三國志·魏書十五》', '太祖征馬超，至弘農，曰「此西道之要」，以逵領弘農太守。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0134-a04-015-28', 'p0134', 'sanguozhi', 'a04-015', '《三國志·魏書十五》', '十六年，馬超反，大軍西討，沛隨軍，都督孟津渡事。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0134-a04-016-29', 'p0134', 'sanguozhi', 'a04-016', '《三國志·魏書十六》', '韓遂、馬超之叛也，弘農、馮翊多舉縣邑以應之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0134-a04-016-30', 'p0134', 'sanguozhi', 'a04-016', '《三國志·魏書十六》', '始，京兆從馬超破後，民人多不專於農殖，又歷數四二千石，取解目前，亦不為民作乆遠計。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0134-a04-017-31', 'p0134', 'sanguozhi', 'a04-017', '《三國志·魏書十七》', '從破馬超、韓遂於渭南。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0134-a04-017-32', 'p0134', 'sanguozhi', 'a04-017', '《三國志·魏書十七》', '韓遂、馬超等反關右，遣晃屯汾陰以撫河東，賜牛酒，令上先人墓。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0134-a04-018-33', 'p0134', 'sanguozhi', 'a04-018', '《三國志·魏書十八》', '從討韓遂、馬超於潼關。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0134-a04-018-34', 'p0134', 'sanguozhi', 'a04-018', '《三國志·魏書十八》', '馬超走奔上邽，郡人任養等舉衆迎之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0134-a04-021-35', 'p0134', 'sanguozhi', 'a04-021', '《三國志·魏書二十一》', '又典略載太祖初征荊州，使瑀作書與劉備，及征馬超，又使瑀作書與韓遂，此二書今具存。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0134-a04-022-36', 'p0134', 'sanguozhi', 'a04-022', '《三國志·魏書二十二》', '會馬超作亂，大軍西征，太祖見官屬曰：「今當遠征，而此方未定，以為後憂，宜得清公大德以鎮統之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0134-a04-023-37', 'p0134', 'sanguozhi', 'a04-023', '《三國志·魏書二十三》', '太祖徙出故韓遂、馬超等兵五千餘人，使平難將軍殷署等督領，以儼為關中護軍，盡統諸軍。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0134-a04-023-38', 'p0134', 'sanguozhi', 'a04-023', '《三國志·魏書二十三》', '及馬超反，幹郡近超，民人分散。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0134-a04-024-39', 'p0134', 'sanguozhi', 'a04-024', '《三國志·魏書二十四》', '太祖欲遣鍾繇等討張魯，柔諫，以為今猥遣大兵，西有韓遂、馬超，謂為己舉，將相扇動作逆，宜先招集三輔，三輔苟平，漢中可傳檄而定也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0134-a04-024-40', 'p0134', 'sanguozhi', 'a04-024', '《三國志·魏書二十四》', '是以周、鄭交惡，漢高請羹，隗嚻捐子，馬超背父，其為酷忍如此之極也，安在其因質委誠，取任永固哉？');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0134-a04-025-41', 'p0134', 'sanguozhi', 'a04-025', '《三國志·魏書二十五》', '馬超之戰敗渭南也，走保諸戎。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0134-a04-025-42', 'p0134', 'sanguozhi', 'a04-025', '《三國志·魏書二十五》', '馬超背父叛君，虐殺州將，豈獨阜之憂責，一州士大夫皆蒙其恥。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0134-a04-025-43', 'p0134', 'sanguozhi', 'a04-025', '《三國志·魏書二十五》', '建安中，馬超攻兾，害涼州刺史韋康，州人悽然，莫不感憤。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0134-a04-025-44', 'p0134', 'sanguozhi', 'a04-025', '《三國志·魏書二十五》', '會馬超攻兾，異躬著布韝，佐昂守備，又悉脫所佩環、黼黻以賞戰士。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0134-a04-025-45', 'p0134', 'sanguozhi', 'a04-025', '《三國志·魏書二十五》', '會劉備遣張飛、馬超等從沮道趣下辯，而氐雷定等七部萬餘落反應之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0134-a04-030-46', 'p0134', 'sanguozhi', 'a04-030', '《三國志·魏書三十》', '近去建安中，興國氐王阿貴、白項氐王千萬各有部落萬餘，至十六年，從馬超為亂。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0134-a04-032-47', 'p0134', 'sanguozhi', 'a04-032', '《三國志·蜀書二》', '先主復領益州牧，諸葛亮為股肱，法正為謀主，關羽、張飛、馬超為爪牙，許靖、麋笁、簡雍為賔友。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0134-a04-032-48', 'p0134', 'sanguozhi', 'a04-032', '《三國志·蜀書二》', '秋，羣下上先主為漢中王，表於漢帝曰：「平西將軍都亭侯臣馬超、左將軍長史領鎮軍將軍臣許靖、營司馬臣龐羲、議曹從事中郎軍議中郎將臣射援、三輔決錄注曰：援字文雄，扶風人也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0134-a04-033-49', 'p0134', 'sanguozhi', 'a04-033', '《三國志·蜀書三》', '三年秋九月，追謚故將軍關羽、張飛、馬超、龐統、黃忠。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0134-a04-036-50', 'p0134', 'sanguozhi', 'a04-036', '《三國志·蜀書六》', '羽聞馬超來降，舊非故人，羽書與諸葛亮，問超人才可誰比類。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0134-a04-036-51', 'p0134', 'sanguozhi', 'a04-036', '《三國志·蜀書六》', '馬超字孟起，右扶風茂陵人也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0134-a04-036-52', 'p0134', 'sanguozhi', 'a04-036', '《三國志·蜀書六》', '故羽聞馬超歸降，以書問諸葛亮「超人才可誰比類」，不得如書所云。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0134-a04-036-53', 'p0134', 'sanguozhi', 'a04-036', '《三國志·蜀書六》', '初，先主時，惟法正見謚；後主時，諸葛亮功德蓋世，蔣琬、費禕荷國之重，亦見謚；陳祗寵待，特加殊獎，夏侯霸遠來歸國，故復得謚；於是關羽、張飛、馬超、龐統、黃忠及雲乃追謚，時論以為榮。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0134-a04-036-54', 'p0134', 'sanguozhi', 'a04-036', '《三國志·蜀書六》', '馬超阻戎負勇，以覆其族，惜哉！');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0134-a04-040-55', 'p0134', 'sanguozhi', 'a04-040', '《三國志·蜀書十》', '羕聞當遠出，私情不恱，往詣馬超。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0134-a04-043-56', 'p0134', 'sanguozhi', 'a04-043', '《三國志·蜀書十三》', '先主嘉之，從至雒城，遣恢至漢中交好馬超，超遂從命。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0134-a04-054-57', 'p0134', 'sanguozhi', 'a04-054', '《三國志·吳書九》', '今北土旣未平安，加馬超、韓遂尚在關西，為操後患。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0134-a04-054-58', 'p0134', 'sanguozhi', 'a04-054', '《三國志·吳書九》', '乞與奮威俱進取蜀，得蜀而并張魯，因留奮威固守其地，好與馬超結援。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0135-a03-053-0', 'p0135', 'houhanshu', 'a03-053', '《後漢書·卷五十三》', '大將軍何進連徵不詣，進必欲致之，使蟠同郡黃忠書勸曰：「前莫府初開，至如先生，特加殊禮，優而不名，申以手筆，設几杖之坐。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0135-a04-032-1', 'p0135', 'sanguozhi', 'a04-032', '《三國志·蜀書二》', '乃使黃忠、卓膺勒兵向璋。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0135-a04-032-2', 'p0135', 'sanguozhi', 'a04-032', '《三國志·蜀書二》', '先主命黃忠乘高鼓譟攻之，大破淵軍，斬淵及曹公所署益州刺史趙顒等。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0135-a04-032-3', 'p0135', 'sanguozhi', 'a04-032', '《三國志·蜀書二》', '軍師將軍臣諸葛亮、盪寇將軍漢壽亭侯臣關羽、征虜將軍新亭侯臣張飛、征西將軍臣黃忠、鎮遠將軍臣賴恭、揚武將軍臣法正、興業將軍臣李嚴等一百二十人上言曰：昔唐堯至聖而四凶在朝，周成仁賢而四國作難，高后稱制而諸呂竊命，孝昭幼冲而上官逆謀，皆馮世寵，藉履國權，窮凶極亂，社稷幾危。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0135-a04-033-4', 'p0135', 'sanguozhi', 'a04-033', '《三國志·蜀書三》', '三年秋九月，追謚故將軍關羽、張飛、馬超、龐統、黃忠。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0135-a04-036-5', 'p0135', 'sanguozhi', 'a04-036', '《三國志·蜀書六》', '黃忠字漢升，南陽人也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0135-a04-036-6', 'p0135', 'sanguozhi', 'a04-036', '《三國志·蜀書六》', '黃忠以為可取，雲兵隨忠取米。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0135-a04-036-7', 'p0135', 'sanguozhi', 'a04-036', '《三國志·蜀書六》', '初，先主時，惟法正見謚；後主時，諸葛亮功德蓋世，蔣琬、費禕荷國之重，亦見謚；陳祗寵待，特加殊獎，夏侯霸遠來歸國，故復得謚；於是關羽、張飛、馬超、龐統、黃忠及雲乃追謚，時論以為榮。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0135-a04-036-8', 'p0135', 'sanguozhi', 'a04-036', '《三國志·蜀書六》', '黃忠、趙雲彊摯壯猛，並作爪牙，其灌、滕之徒歟？');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0135-a04-037-9', 'p0135', 'sanguozhi', 'a04-037', '《三國志·蜀書七》', '」先主命黃忠乘高鼓譟攻之，大破淵軍，淵等授首。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0135-a04-041-10', 'p0135', 'sanguozhi', 'a04-041', '《三國志·蜀書十一》', '先主為漢中王，遣詩拜關羽為前將軍，羽聞黃忠為後將軍，羽怒曰：「大丈夫終不與老兵同列！');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0136-a04-006-0', 'p0136', 'sanguozhi', 'a04-006', '《三國志·魏書六》', '文帝時為侍中，太和中卒，巽在荊州，目龐統為半英雄，證裴潛終以清行顯；統遂附劉備，見待次於諸葛亮，潛位至尚書令，並有名德。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0136-a04-032-1', 'p0136', 'sanguozhi', 'a04-032', '《三國志·蜀書二》', '張松令法正白先主，及謀臣龐統進說，便可於會所襲璋。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0136-a04-033-2', 'p0136', 'sanguozhi', 'a04-033', '《三國志·蜀書三》', '三年秋九月，追謚故將軍關羽、張飛、馬超、龐統、黃忠。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0136-a04-036-3', 'p0136', 'sanguozhi', 'a04-036', '《三國志·蜀書六》', '初，先主時，惟法正見謚；後主時，諸葛亮功德蓋世，蔣琬、費禕荷國之重，亦見謚；陳祗寵待，特加殊獎，夏侯霸遠來歸國，故復得謚；於是關羽、張飛、馬超、龐統、黃忠及雲乃追謚，時論以為榮。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0136-a04-037-4', 'p0136', 'sanguozhi', 'a04-037', '《三國志·蜀書七》', '龐統字士元，襄陽人也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0136-a04-037-5', 'p0136', 'sanguozhi', 'a04-037', '《三國志·蜀書七》', '龐統懼斯言之泄宣，知其君之必悟，故衆中匡其失，而不脩常謙之道，矯然太當，盡其謇諤之風。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0136-a04-037-6', 'p0136', 'sanguozhi', 'a04-037', '《三國志·蜀書七》', '評曰：龐統雅好人流，經學思謀，于時荊、楚謂之高俊。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0136-a04-040-7', 'p0136', 'sanguozhi', 'a04-040', '《三國志·蜀書十》', '羕欲納說先主，乃往見龐統。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0136-a04-040-8', 'p0136', 'sanguozhi', 'a04-040', '《三國志·蜀書十》', '會公來西，僕因法孝直自衒鬻，龐統斟酌其間，遂得詣公於葭萌，指掌而譚，論治世之務，講霸王之業，建取益州之策，公亦宿慮明定，即相然贊，遂舉事焉。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0136-a04-040-9', 'p0136', 'sanguozhi', 'a04-040', '《三國志·蜀書十》', '昔每與龐統共相誓約，庶託足下末蹤，盡心於主公之業，追名古人，載勳竹帛。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0136-a04-040-10', 'p0136', 'sanguozhi', 'a04-040', '《三國志·蜀書十》', '先主入蜀，諸葛亮鎮荊土，孫權遣使通好於亮，因問士人皆誰相經緯者，亮荅曰：「龐統、廖立，楚之良才，當贊興世業者也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0136-a04-045-11', 'p0136', 'sanguozhi', 'a04-045', '《三國志·蜀書十五》', '存素不服龐統，統中矢卒，先主發言嘉歎，存曰：「統雖盡忠可惜，然違大雅之義。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0136-a04-045-12', 'p0136', 'sanguozhi', 'a04-045', '《三國志·蜀書十五》', '襄陽記曰：習禎有風流，善談論，名亞龐統，而在馬良之右。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0136-a04-057-13', 'p0136', 'sanguozhi', 'a04-057', '《三國志·吳書十二》', '虞翻舊齒名盛，龐統荊州令士，年亦差長，皆與績友善。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0137-a03-075-0', 'p0137', 'houhanshu', 'a03-075', '《後漢書·卷七十五》', '蜀志曰：「法正字孝直，扶風郿人也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0137-a04-013-1', 'p0137', 'sanguozhi', 'a04-013', '《三國志·卷十三‧魏書十三》', '臣又疾病，前後歷年，氣力日微，尸素重祿，曠廢職任，罪明法正。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0137-a04-031-2', 'p0137', 'sanguozhi', 'a04-031', '《三國志·蜀書一》', '」璋皆然之，遣法正連好先主，尋又令正及孟達送兵數千助先主守禦，正遂還。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0137-a04-031-3', 'p0137', 'sanguozhi', 'a04-031', '《三國志·蜀書一》', '」璋又從之，遣法正請先主。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0137-a04-031-4', 'p0137', 'sanguozhi', 'a04-031', '《三國志·蜀書一》', '張松、法正，雖有君臣之義不正，然固已委名附質，進不顯陳事勢，若韓嵩、劉先之說劉表，退不告絕奔亡，若陳平、韓信之去項羽，而兩端攜貳，為謀不忠，罪之次也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0137-a04-032-5', 'p0137', 'sanguozhi', 'a04-032', '《三國志·蜀書二》', '」璋然之，遣法正將四千人迎先主，前後賂遺以巨億計。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0137-a04-032-6', 'p0137', 'sanguozhi', 'a04-032', '《三國志·蜀書二》', '吳書曰：備前見張松，後得法正，皆厚以恩意接納，盡其殷勤之歡。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0137-a04-032-7', 'p0137', 'sanguozhi', 'a04-032', '《三國志·蜀書二》', '張松令法正白先主，及謀臣龐統進說，便可於會所襲璋。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0137-a04-032-8', 'p0137', 'sanguozhi', 'a04-032', '《三國志·蜀書二》', '」張松書與先主及法正曰：「今大事垂可立，如何釋此去乎！');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0137-a04-032-9', 'p0137', 'sanguozhi', 'a04-032', '《三國志·蜀書二》', '先主復領益州牧，諸葛亮為股肱，法正為謀主，關羽、張飛、馬超為爪牙，許靖、麋笁、簡雍為賔友。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0137-a04-032-10', 'p0137', 'sanguozhi', 'a04-032', '《三國志·蜀書二》', '軍師將軍臣諸葛亮、盪寇將軍漢壽亭侯臣關羽、征虜將軍新亭侯臣張飛、征西將軍臣黃忠、鎮遠將軍臣賴恭、揚武將軍臣法正、興業將軍臣李嚴等一百二十人上言曰：昔唐堯至聖而四凶在朝，周成仁賢而四國作難，高后稱制而諸呂竊命，孝昭幼冲而上官逆謀，皆馮世寵，藉履國權，窮凶極亂，社稷幾危。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0137-a04-034-11', 'p0137', 'sanguozhi', 'a04-034', '《三國志·蜀書四》', '羣下勸先主聘后，先主疑與瑁同族，法正進曰：「論其親踈，何與晉文之於子圉乎？');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0137-a04-035-12', 'p0137', 'sanguozhi', 'a04-035', '《三國志·蜀書五》', '建安十六年，益州牧劉璋遣法正迎先主，使擊張魯。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0137-a04-035-13', 'p0137', 'sanguozhi', 'a04-035', '《三國志·蜀書五》', '臣松之以為亮之異美，誠所願聞，然冲之所說，實皆可疑，謹隨事難之如左：其一事曰：亮刑法峻急，刻剥百姓，自君子小人咸懷怨歎，法正諫曰：「昔高祖入關，約法三章，秦民知德，今君假借威力，跨據一州，初有其國，未垂惠撫；且客主之義，宜相降下，願緩刑弛禁，以慰其望。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0137-a04-035-14', 'p0137', 'sanguozhi', 'a04-035', '《三國志·蜀書五》', '」難曰：案法正在劉主前死，今稱法正諫，則劉主在也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0137-a04-036-15', 'p0137', 'sanguozhi', 'a04-036', '《三國志·蜀書六》', '益州旣平，賜諸葛亮、法正、飛及關羽金各五百斤，銀千斤，錢五千萬，錦千匹，其餘頒賜各有差，以飛領巴西太守。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0137-a04-036-16', 'p0137', 'sanguozhi', 'a04-036', '《三國志·蜀書六》', '初，先主時，惟法正見謚；後主時，諸葛亮功德蓋世，蔣琬、費禕荷國之重，亦見謚；陳祗寵待，特加殊獎，夏侯霸遠來歸國，故復得謚；於是關羽、張飛、馬超、龐統、黃忠及雲乃追謚，時論以為榮。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0137-a04-037-17', 'p0137', 'sanguozhi', 'a04-037', '《三國志·蜀書七》', '法正字孝直，右扶風郿人也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0137-a04-037-18', 'p0137', 'sanguozhi', 'a04-037', '《三國志·蜀書七》', '法正以靖方隗，未為不當，而盛以封墓式閭為難，何其迃哉！');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0137-a04-037-19', 'p0137', 'sanguozhi', 'a04-037', '《三國志·蜀書七》', '或謂諸葛亮曰：「法正於蜀郡太縱橫，將軍宜啟主公，抑其威福。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0137-a04-037-20', 'p0137', 'sanguozhi', 'a04-037', '《三國志·蜀書七》', '」亮荅曰：「主公之在公安也，北畏曹公之彊，東憚孫權之逼，近則懼孫夫人生變於肘腋之下；當斯之時，進退狼跋，法孝直為之輔翼，令翻然翱翔，不可復制，如何禁止法正使不得行其意邪！');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0137-a04-037-21', 'p0137', 'sanguozhi', 'a04-037', '《三國志·蜀書七》', '法正著見成敗，有奇畫策筭，然不以德素稱也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0137-a04-038-22', 'p0137', 'sanguozhi', 'a04-038', '《三國志·蜀書八》', '後遷昭文將軍，與諸葛亮、法正、劉巴、李嚴共造蜀科；蜀科之制，由此五人焉。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0137-a04-039-23', 'p0137', 'sanguozhi', 'a04-039', '《三國志·蜀書九》', '零陵先賢傳曰：璋遣法正迎劉備，巴諫曰：「備，雄人也，入必為害，不可內也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0137-a04-039-24', 'p0137', 'sanguozhi', 'a04-039', '《三國志·蜀書九》', '建安二十四年，先主為漢中王，巴為尚書，後代法正為尚書令。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0137-a04-040-25', 'p0137', 'sanguozhi', 'a04-040', '《三國志·蜀書十》', '初，劉璋遣扶風孟達副法正，各將兵二千人，使迎先主，先主因令達并領其衆，留屯江陵。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0137-a04-040-26', 'p0137', 'sanguozhi', 'a04-040', '《三國志·蜀書十》', '統大善之，而法正宿自知羕，遂並致之先主。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0137-a04-041-27', 'p0137', 'sanguozhi', 'a04-041', '《三國志·蜀書十一》', '」時蜀郡太守法正從先主北行，亮於是表洪領蜀郡太守，衆事皆辦，遂使即真。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0138-a03-009-0', 'p0138', 'houhanshu', 'a03-009', '《後漢書·卷九》', '山陽公載記曰：「時許靖在巴郡，聞立諸王，曰：『將欲歙之，必姑張之；將欲奪之，必姑與之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0138-a03-068-1', 'p0138', 'houhanshu', 'a03-068', '《後漢書·卷六十八》', '劭邑人李逵，壯直有高氣，劭初善之，而後為隙，又與從兄靖不睦，蜀志曰：「許靖字文休，少與從弟劭俱知名，並有人倫臧否之稱，而私情不協。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0138-a04-013-2', 'p0138', 'sanguozhi', 'a04-013', '《三國志·卷十三‧魏書十三》', '肅父朗與許靖書云：肅生於會稽。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0138-a04-032-3', 'p0138', 'sanguozhi', 'a04-032', '《三國志·蜀書二》', '先主復領益州牧，諸葛亮為股肱，法正為謀主，關羽、張飛、馬超為爪牙，許靖、麋笁、簡雍為賔友。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0138-a04-032-4', 'p0138', 'sanguozhi', 'a04-032', '《三國志·蜀書二》', '秋，羣下上先主為漢中王，表於漢帝曰：「平西將軍都亭侯臣馬超、左將軍長史領鎮軍將軍臣許靖、營司馬臣龐羲、議曹從事中郎軍議中郎將臣射援、三輔決錄注曰：援字文雄，扶風人也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0138-a04-032-5', 'p0138', 'sanguozhi', 'a04-032', '《三國志·蜀書二》', '太傅許靖、安漢將軍糜笁、軍師將軍諸葛亮、太常賴恭、光祿勳黃柱、少府王謀等上言：「曹丕篡弒，湮滅漢室，竊據神器，劫迫忠良，酷烈無道。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0138-a04-032-6', 'p0138', 'sanguozhi', 'a04-032', '《三國志·蜀書二》', '以諸葛亮為丞相，許靖為司徒。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0138-a04-037-7', 'p0138', 'sanguozhi', 'a04-037', '《三國志·蜀書七》', '十九年，進圍成都，璋蜀郡太守許靖將踰城降，事覺，不果。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0138-a04-037-8', 'p0138', 'sanguozhi', 'a04-037', '《三國志·蜀書七》', '正說曰：「天下有獲虛譽而無其實者，許靖是也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0138-a04-038-9', 'p0138', 'sanguozhi', 'a04-038', '《三國志·蜀書八》', '許靖字文休，汝南平輿人。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0138-a04-038-10', 'p0138', 'sanguozhi', 'a04-038', '《三國志·蜀書八》', '許靖羇客會稽，閭閻之士，孫策之來，於靖何為？');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0138-a04-038-11', 'p0138', 'sanguozhi', 'a04-038', '《三國志·蜀書八》', '許靖號為臧否，至蜀，見商而稱之曰：「設使商生於華夏，雖王景興無以加也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0138-a04-038-12', 'p0138', 'sanguozhi', 'a04-038', '《三國志·蜀書八》', '在郡十載，卒於官，許靖代之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0138-a04-038-13', 'p0138', 'sanguozhi', 'a04-038', '《三國志·蜀書八》', '評曰：許靖夙有名譽，旣以篤厚為稱，又以人物為意，雖行事舉動，未悉允當，蔣濟以為「大較廊廟器」也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0138-a04-039-14', 'p0138', 'sanguozhi', 'a04-039', '《三國志·蜀書九》', '祗字奉宗，汝南人，許靖兄之外孫也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0138-a04-040-15', 'p0138', 'sanguozhi', 'a04-040', '《三國志·蜀書十》', '姿性驕傲，多所輕忽，惟敬同郡秦子勑，薦之於太守許靖曰：「昔高宗夢傅說，周文求呂尚，爰及漢祖，納食其於布衣，此乃帝王之所以倡業垂統，緝熈厥功也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0138-a04-042-16', 'p0138', 'sanguozhi', 'a04-042', '《三國志·蜀書十二》', '建安中，與許靖等俱自交州入蜀。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0138-a04-044-17', 'p0138', 'sanguozhi', 'a04-044', '《三國志·蜀書十四》', '時許靖喪子，允與禕欲共會其葬所。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0140-a04-032-0', 'p0140', 'sanguozhi', 'a04-032', '《三國志·蜀書二》', '東海昌霸反，郡縣多叛曹公為先主，衆數萬人，遣孫乾與袁紹連和，曹公遣劉岱、王忠擊之，不克。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0140-a04-032-1', 'p0140', 'sanguozhi', 'a04-032', '《三國志·蜀書二》', '先主遣麋笁、孫乾與劉表相聞，表自郊迎，以上賔禮待之，益其兵，使屯新野。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0140-a04-038-2', 'p0140', 'sanguozhi', 'a04-038', '《三國志·蜀書八》', '孫乾字公祐，北海人也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0140-a04-038-3', 'p0140', 'sanguozhi', 'a04-038', '《三國志·蜀書八》', '先主至荊州，雍與麋笁、孫乾同為從事中郎，常為談客，往來使命。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0140-a04-038-4', 'p0140', 'sanguozhi', 'a04-038', '《三國志·蜀書八》', '益州旣定，以籍為左將軍從事中郎，見待亞於簡雍、孫乾等。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0140-a04-038-5', 'p0140', 'sanguozhi', 'a04-038', '《三國志·蜀書八》', '麋笁、孫乾、簡雍、伊籍，皆雍容風議，見禮於世。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0141-a04-032-0', 'p0141', 'sanguozhi', 'a04-032', '《三國志·蜀書二》', '先主復領益州牧，諸葛亮為股肱，法正為謀主，關羽、張飛、馬超為爪牙，許靖、麋笁、簡雍為賔友。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0141-a04-038-1', 'p0141', 'sanguozhi', 'a04-038', '《三國志·蜀書八》', '先主定益州，乾自從事中郎為秉忠將軍，見禮次麋笁，與簡雍同等。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0141-a04-038-2', 'p0141', 'sanguozhi', 'a04-038', '《三國志·蜀書八》', '簡雍字憲和，涿郡人也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0141-a04-038-3', 'p0141', 'sanguozhi', 'a04-038', '《三國志·蜀書八》', '益州旣定，以籍為左將軍從事中郎，見待亞於簡雍、孫乾等。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0141-a04-038-4', 'p0141', 'sanguozhi', 'a04-038', '《三國志·蜀書八》', '麋笁、孫乾、簡雍、伊籍，皆雍容風議，見禮於世。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0142-a04-038-0', 'p0142', 'sanguozhi', 'a04-038', '《三國志·蜀書八》', '麋笁、孫乾、簡雍、伊籍，皆雍容風議，見禮於世。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0143-a04-031-0', 'p0143', 'sanguozhi', 'a04-031', '《三國志·蜀書一》', '後丞相諸葛亮問秦宓以扶所長，宓曰：「董扶襃秋毫之善，貶纖芥之惡。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0143-a04-038-1', 'p0143', 'sanguozhi', 'a04-038', '《三國志·蜀書八》', '秦宓字子勑，廣漢緜竹人也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0143-a04-038-2', 'p0143', 'sanguozhi', 'a04-038', '《三國志·蜀書八》', '後丞相亮問秦宓以安所長，宓曰：「記人之善，忘人之過。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0143-a04-038-3', 'p0143', 'sanguozhi', 'a04-038', '《三國志·蜀書八》', '秦宓始慕肥遯之高，而無若愚之實。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0143-a04-040-4', 'p0143', 'sanguozhi', 'a04-040', '《三國志·蜀書十》', '伏見處士緜竹秦宓，膺山甫之德，履雋生之直，枕石漱流，吟詠縕袍，偃息於仁義之途，恬惔於浩然之域，高概節行，守真不虧，雖古人潛遁，蔑以加旃。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0143-a04-042-5', 'p0143', 'sanguozhi', 'a04-042', '《三國志·蜀書十二》', '建興二年，丞相亮領益州牧，選迎皆妙簡舊德，以秦宓為別駕，五梁為功曹，微為主簿。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0144-a04-020-0', 'p0144', 'sanguozhi', 'a04-020', '《三國志·魏書二十》', '魏書載璽書曰：「制詔彭城王：有司奏，王遣司馬董和，齎珠玉來到京師中尚方，多作禁物，交通工官，出入近署，踰侈非度，慢令違制，繩王以法。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0144-a04-032-1', 'p0144', 'sanguozhi', 'a04-032', '《三國志·蜀書二》', '及董和、黃權、李嚴等本璋之所授用也，吳壹、費觀等又璋之婚親也，彭羡又璋之所排擯也，劉巴者宿昔之所忌恨也，皆處之顯任，盡其器能。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0144-a04-039-2', 'p0144', 'sanguozhi', 'a04-039', '《三國志·蜀書九》', '董和字幼宰，南郡枝江人也，其先本巴郡江州人。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0144-a04-039-3', 'p0144', 'sanguozhi', 'a04-039', '《三國志·蜀書九》', '評曰：董和蹈羔羊之素，劉巴履清尚之節，馬良貞實，稱為令士，陳震忠恪，老而益篤，董允匡主，義形於色，皆蜀臣之良矣。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0144-a04-043-4', 'p0144', 'sanguozhi', 'a04-043', '《三國志·蜀書十三》', '太守董和以習方土大姓，寢而不許。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0144-a04-047-5', 'p0144', 'sanguozhi', 'a04-047', '《三國志·吳書二》', '閏月，克之，獲廬江太守朱光及參軍董和，男女數萬口。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0145-a04-032-0', 'p0145', 'sanguozhi', 'a04-032', '《三國志·蜀書二》', '及董和、黃權、李嚴等本璋之所授用也，吳壹、費觀等又璋之婚親也，彭羡又璋之所排擯也，劉巴者宿昔之所忌恨也，皆處之顯任，盡其器能。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0145-a04-038-1', 'p0145', 'sanguozhi', 'a04-038', '《三國志·蜀書八》', '後遷昭文將軍，與諸葛亮、法正、劉巴、李嚴共造蜀科；蜀科之制，由此五人焉。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0145-a04-039-2', 'p0145', 'sanguozhi', 'a04-039', '《三國志·蜀書九》', '劉巴字子初，零陵烝陽人也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0145-a04-039-3', 'p0145', 'sanguozhi', 'a04-039', '《三國志·蜀書九》', '評曰：董和蹈羔羊之素，劉巴履清尚之節，馬良貞實，稱為令士，陳震忠恪，老而益篤，董允匡主，義形於色，皆蜀臣之良矣。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0145-a04-040-4', 'p0145', 'sanguozhi', 'a04-040', '《三國志·蜀書十》', '輙與行中軍師車騎將軍都鄉侯臣劉琰，使持節前軍師征西大將軍領涼州刺史南鄭侯臣魏延、前將軍都亭侯臣袁綝、左將軍領荊州刺史高陽鄉侯臣吳壹、督前部右將軍玄鄉侯臣高翔、督後部後將軍安樂亭侯臣吳班、領長史綏軍將軍臣楊儀、督左部行中監軍揚武將軍臣鄧芝、行前監軍征南將軍臣劉巴、行中護軍偏將軍臣費禕、行前護軍偏將軍漢成亭侯臣許允、行左護軍篤信中郎將臣丁咸、行右護軍偏將軍臣劉敏、行護軍征南將軍當陽亭侯臣姜維、行中典軍討虜將軍臣上官雝、行中參軍昭武中郎將臣胡濟、行參軍建議將軍臣閻晏、行參軍偏將軍臣爨習、行參軍裨將軍臣杜義、行參軍武略中郎將臣杜祺、行參軍綏戎都尉臣盛勃、領從事中郎武略中郎將臣樊岐等議，輙解平任，免官祿、節傳、印綬、符策，削其爵土。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0145-a04-040-5', 'p0145', 'sanguozhi', 'a04-040', '《三國志·蜀書十》', '先主稱尊號，東征吳，儀與尚書令劉巴不睦，左遷遙署弘農太守。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0145-a04-043-6', 'p0145', 'sanguozhi', 'a04-043', '《三國志·蜀書十三》', '先主已還永安，見忠與語，謂尚書令劉巴曰：「雖亡黃權，復得狐篤，此為世不乏賢也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0146-a04-032-0', 'p0146', 'sanguozhi', 'a04-032', '《三國志·蜀書二》', '通武陵，遣侍中馬良安慰五谿蠻夷，咸相率響應。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0146-a04-039-1', 'p0146', 'sanguozhi', 'a04-039', '《三國志·蜀書九》', '馬良字季常，襄陽宜城人也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0146-a04-039-2', 'p0146', 'sanguozhi', 'a04-039', '《三國志·蜀書九》', '」良即為草曰：「寡君遣掾馬良通聘繼好，以紹昆吾、豕韋之勳。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0146-a04-039-3', 'p0146', 'sanguozhi', 'a04-039', '《三國志·蜀書九》', '評曰：董和蹈羔羊之素，劉巴履清尚之節，馬良貞實，稱為令士，陳震忠恪，老而益篤，董允匡主，義形於色，皆蜀臣之良矣。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0146-a04-040-4', 'p0146', 'sanguozhi', 'a04-040', '《三國志·蜀書十》', '恭作治中無綱紀；朗昔奉馬良兄弟，謂為聖人，今作長史，素能合道。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0146-a04-045-5', 'p0146', 'sanguozhi', 'a04-045', '《三國志·蜀書十五》', '襄陽記曰：習禎有風流，善談論，名亞龐統，而在馬良之右。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0147-a04-003-0', 'p0147', 'sanguozhi', 'a04-003', '《三國志·魏書三》', '王師方振，膽破氣奪，馬謖、高祥望旗奔敗。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0147-a04-009-1', 'p0147', 'sanguozhi', 'a04-009', '《三國志·魏書九》', '帝遣真督諸軍軍郿，遣張郃擊亮將馬謖，大破之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0147-a04-017-2', 'p0147', 'sanguozhi', 'a04-017', '《三國志·魏書十七》', '加郃位特進，遣督諸軍，拒亮將馬謖於街亭。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0147-a04-026-3', 'p0147', 'sanguozhi', 'a04-026', '《三國志·魏書二十六》', '太和二年，蜀相諸葛亮出祁山，遣將軍馬謖至街亭，高詳屯列柳城。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0147-a04-035-4', 'p0147', 'sanguozhi', 'a04-035', '《三國志·蜀書五》', '魏明帝西鎮長安，命張郃拒亮，亮使馬謖督諸軍在前，與郃戰于街亭。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0147-a04-035-5', 'p0147', 'sanguozhi', 'a04-035', '《三國志·蜀書五》', '詔策亮曰：「街亭之役，咎由馬謖，而君引愆，深自貶抑，重違君意，聽順所守。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0147-a04-039-6', 'p0147', 'sanguozhi', 'a04-039', '《三國志·蜀書九》', '先主臨薨謂亮曰：「馬謖言過其實，不可大用，君其察之！');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0147-a04-041-7', 'p0147', 'sanguozhi', 'a04-041', '《三國志·蜀書十一》', '朗素與馬謖善，謖逃亡，朗知情不舉，亮恨之，免官還成都。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0147-a04-041-8', 'p0147', 'sanguozhi', 'a04-041', '《三國志·蜀書十一》', '自去長史，優游無事垂三十年，臣松之案：朗坐馬謖免長史，則建興六年中也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0147-a04-043-9', 'p0147', 'sanguozhi', 'a04-043', '《三國志·蜀書十三》', '建興六年，屬參軍馬謖先鋒。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0147-a04-043-10', 'p0147', 'sanguozhi', 'a04-043', '《三國志·蜀書十三》', '丞相亮旣誅馬謖及將軍張休、李盛，奪將軍黃襲等兵，平特見崇顯，加拜參軍，統五部兼當營事，進位討寇將軍，封亭侯。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0147-a04-044-11', 'p0147', 'sanguozhi', 'a04-044', '《三國志·蜀書十四》', '會馬謖敗於街亭，亮拔將西縣千餘家及維等還，故維遂與母相失。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0147-a04-045-12', 'p0147', 'sanguozhi', 'a04-045', '《三國志·蜀書十五》', '馬謖在前敗績，亮將殺之，邈諫以「秦赦孟明，用霸西戎，楚誅子玉，二世不競」，失亮意，還蜀。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0148-a04-035-0', 'p0148', 'sanguozhi', 'a04-035', '《三國志·蜀書五》', '」乃遣衞尉陳震慶權正號。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0148-a04-039-1', 'p0148', 'sanguozhi', 'a04-039', '《三國志·蜀書九》', '陳震字孝起，南陽人也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0148-a04-039-2', 'p0148', 'sanguozhi', 'a04-039', '《三國志·蜀書九》', '評曰：董和蹈羔羊之素，劉巴履清尚之節，馬良貞實，稱為令士，陳震忠恪，老而益篤，董允匡主，義形於色，皆蜀臣之良矣。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0148-a04-047-3', 'p0148', 'sanguozhi', 'a04-047', '《三國志·吳書二》', '六月，蜀遣衞尉陳震慶權踐位。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0149-a04-035-0', 'p0149', 'sanguozhi', 'a04-035', '《三國志·蜀書五》', '侍中、侍郎郭攸之、費禕、董允等，此皆良實，志慮忠純，是以先帝簡拔以遺陛下。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0149-a04-039-1', 'p0149', 'sanguozhi', 'a04-039', '《三國志·蜀書九》', '九年，都護李平坐誣罔廢；諸葛亮與長史蔣琬、侍中董允書曰：「孝起前臨至吳，為吾說正方腹中有鱗甲，鄉黨以為不可近。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0149-a04-039-2', 'p0149', 'sanguozhi', 'a04-039', '《三國志·蜀書九》', '董允字休昭，掌軍中郎將和之子也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0149-a04-039-3', 'p0149', 'sanguozhi', 'a04-039', '《三國志·蜀書九》', '上疏曰：「侍中郭攸之 ‧ 費禕、侍郎董允等，先帝簡拔以遺陛下，至於斟酌規益，進盡忠言，則其任也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0149-a04-039-4', 'p0149', 'sanguozhi', 'a04-039', '《三國志·蜀書九》', '臣松之以為陳羣子泰，陸遜子抗，傳皆以子繫父，不別載姓，及王肅、杜恕、張承、顧劭之流，莫不皆然，惟董允獨否，未詳其意，當以允名位優重，事跡踰父故邪？');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0149-a04-039-5', 'p0149', 'sanguozhi', 'a04-039', '《三國志·蜀書九》', '後入為尚書，代董允為尚書令，衆事無留，門無停賔。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0149-a04-039-6', 'p0149', 'sanguozhi', 'a04-039', '《三國志·蜀書九》', '評曰：董和蹈羔羊之素，劉巴履清尚之節，馬良貞實，稱為令士，陳震忠恪，老而益篤，董允匡主，義形於色，皆蜀臣之良矣。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0149-a04-040-7', 'p0149', 'sanguozhi', 'a04-040', '《三國志·蜀書十》', '後主以問侍中董允、留府長史蔣琬，琬、允咸保儀疑延。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0149-a04-044-8', 'p0149', 'sanguozhi', 'a04-044', '《三國志·蜀書十四》', '會先主定蜀，禕遂留益土，與汝南許叔龍、南郡董允齊名。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0149-a04-044-9', 'p0149', 'sanguozhi', 'a04-044', '《三國志·蜀書十四》', '董允代禕為尚書令，欲斆禕之所行，旬日之中，事多愆滯。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0149-a04-044-10', 'p0149', 'sanguozhi', 'a04-044', '《三國志·蜀書十四》', '後主曰：「皓趨走小臣耳，往董允切齒，吾常恨之，君何足介意！');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0150-a04-039-0', 'p0150', 'sanguozhi', 'a04-039', '《三國志·蜀書九》', '呂乂卒，祗又以侍中守尚書令，加鎮軍將軍，大將軍姜維雖班在祗上，常率衆在外，希親朝政。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0150-a04-039-1', 'p0150', 'sanguozhi', 'a04-039', '《三國志·蜀書九》', '呂乂字季陽，南陽人也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0150-a04-039-2', 'p0150', 'sanguozhi', 'a04-039', '《三國志·蜀書九》', '呂乂臨郡則垂稱，處朝則被損，亦黃、薛之流亞矣。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0150-a04-041-3', 'p0150', 'sanguozhi', 'a04-041', '《三國志·蜀書十一》', '遷司鹽校尉，較鹽鐵之利，利入甚多，有裨國用，於是簡取良才以為官屬，若呂乂、杜祺、劉幹等，終皆至大官，自連所拔也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0151-a04-003-0', 'p0151', 'sanguozhi', 'a04-003', '《三國志·魏書三》', '干寶晉紀曰：達初入新城，登白馬塞，歎曰：「劉封、申耽，據金城千里而失之乎！');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0151-a04-019-1', 'p0151', 'sanguozhi', 'a04-019', '《三國志·魏書十九》', '」魏略曰：太祖在漢中，而劉備栖於山頭，使劉封下挑戰。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0151-a04-032-2', 'p0151', 'sanguozhi', 'a04-032', '《三國志·蜀書二》', '遣劉封、孟達、李平等攻申耽於上庸。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0151-a04-040-3', 'p0151', 'sanguozhi', 'a04-040', '《三國志·蜀書十》', '劉封者，本羅侯寇氏之子，長沙劉氏之甥也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0151-a04-040-4', 'p0151', 'sanguozhi', 'a04-040', '《三國志·蜀書十》', '評曰：劉封處嫌疑之地，而思防不足以自衞。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0151-a04-041-5', 'p0151', 'sanguozhi', 'a04-041', '《三國志·蜀書十一》', '嗚呼孟子，斯實劉封侵陵足下，以傷先主待士之義。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0152-a04-040-0', 'p0152', 'sanguozhi', 'a04-040', '《三國志·蜀書十》', '彭羕、廖立以才拔進，李嚴以幹局達，魏延以勇略任，楊儀以當官顯，劉琰舊仕，並咸貴重。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0153-a04-040-0', 'p0153', 'sanguozhi', 'a04-040', '《三國志·蜀書十》', '先主入蜀，諸葛亮鎮荊土，孫權遣使通好於亮，因問士人皆誰相經緯者，亮荅曰：「龐統、廖立，楚之良才，當贊興世業者也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0153-a04-040-1', 'p0153', 'sanguozhi', 'a04-040', '《三國志·蜀書十》', '亮表立曰：「長水校尉廖立，坐自貴大，臧否羣士，公言國家不任賢達而任俗吏，又言萬人率者皆小子也；誹謗先帝，疵毀衆臣。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0153-a04-040-2', 'p0153', 'sanguozhi', 'a04-040', '《三國志·蜀書十》', '」詔曰：「三苗亂政，有虞流宥，廖立狂惑，朕不忍刑，亟徙不毛之地。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0153-a04-040-3', 'p0153', 'sanguozhi', 'a04-040', '《三國志·蜀書十》', '諸葛亮之使廖立垂泣，李平致死，豈徒無怨言而已哉！');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0153-a04-040-4', 'p0153', 'sanguozhi', 'a04-040', '《三國志·蜀書十》', '彭羕、廖立以才拔進，李嚴以幹局達，魏延以勇略任，楊儀以當官顯，劉琰舊仕，並咸貴重。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0154-a04-032-0', 'p0154', 'sanguozhi', 'a04-032', '《三國志·蜀書二》', '璋復遣李嚴督緜竹諸軍，嚴率衆降先主。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0154-a04-032-1', 'p0154', 'sanguozhi', 'a04-032', '《三國志·蜀書二》', '及董和、黃權、李嚴等本璋之所授用也，吳壹、費觀等又璋之婚親也，彭羡又璋之所排擯也，劉巴者宿昔之所忌恨也，皆處之顯任，盡其器能。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0154-a04-032-2', 'p0154', 'sanguozhi', 'a04-032', '《三國志·蜀書二》', '軍師將軍臣諸葛亮、盪寇將軍漢壽亭侯臣關羽、征虜將軍新亭侯臣張飛、征西將軍臣黃忠、鎮遠將軍臣賴恭、揚武將軍臣法正、興業將軍臣李嚴等一百二十人上言曰：昔唐堯至聖而四凶在朝，周成仁賢而四國作難，高后稱制而諸呂竊命，孝昭幼冲而上官逆謀，皆馮世寵，藉履國權，窮凶極亂，社稷幾危。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0154-a04-032-3', 'p0154', 'sanguozhi', 'a04-032', '《三國志·蜀書二》', '先主病篤，託孤於丞相亮，尚書令李嚴為副。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0154-a04-033-4', 'p0154', 'sanguozhi', 'a04-033', '《三國志·蜀書三》', '四年春，都護李嚴自永安還住江州，築大城。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0154-a04-038-5', 'p0154', 'sanguozhi', 'a04-038', '《三國志·蜀書八》', '後遷昭文將軍，與諸葛亮、法正、劉巴、李嚴共造蜀科；蜀科之制，由此五人焉。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0154-a04-040-6', 'p0154', 'sanguozhi', 'a04-040', '《三國志·蜀書十》', '立本意，自謂才名宜為諸葛亮之貳，而更游散在李嚴等下，常懷怏怏。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0154-a04-040-7', 'p0154', 'sanguozhi', 'a04-040', '《三國志·蜀書十》', '李嚴字正方，南陽人也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0154-a04-040-8', 'p0154', 'sanguozhi', 'a04-040', '《三國志·蜀書十》', '後主立，封都鄉侯，班位每亞李嚴，為衞尉中軍師後將軍，遷車騎將軍。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0154-a04-040-9', 'p0154', 'sanguozhi', 'a04-040', '《三國志·蜀書十》', '彭羕、廖立以才拔進，李嚴以幹局達，魏延以勇略任，楊儀以當官顯，劉琰舊仕，並咸貴重。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0154-a04-041-10', 'p0154', 'sanguozhi', 'a04-041', '《三國志·蜀書十一》', '先主定蜀，太守李嚴命為功曹。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0154-a04-041-11', 'p0154', 'sanguozhi', 'a04-041', '《三國志·蜀書十一》', '始洪為李嚴功曹，嚴未至犍為而洪已為蜀郡。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0154-a04-041-12', 'p0154', 'sanguozhi', 'a04-041', '《三國志·蜀書十一》', '為牙門將，統屬江州督李嚴。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0154-a04-043-13', 'p0154', 'sanguozhi', 'a04-043', '《三國志·蜀書十三》', '都護李嚴與闓書六紙，解喻利害，闓但荅一紙曰：「蓋聞天無二日，土無二王，今天下鼎立，正朔有三，是以遠人惶惑，不知所歸也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0154-a04-045-14', 'p0154', 'sanguozhi', 'a04-045', '《三國志·蜀書十五》', '觀建安十八年參李嚴軍，拒先主於緜竹，與嚴俱降，先主旣定益州，拜為裨將軍，後為巴郡太守、江州都督，建興元年封都亭侯，加振威將軍。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0154-a04-045-15', 'p0154', 'sanguozhi', 'a04-045', '《三國志·蜀書十五》', '都護李嚴性自矜高，護軍輔匡等年位與嚴相次，而嚴不與親褻；觀年少嚴二十餘歲，而與嚴通狎如時輩云。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0155-a04-040-0', 'p0155', 'sanguozhi', 'a04-040', '《三國志·蜀書十》', '輙與行中軍師車騎將軍都鄉侯臣劉琰，使持節前軍師征西大將軍領涼州刺史南鄭侯臣魏延、前將軍都亭侯臣袁綝、左將軍領荊州刺史高陽鄉侯臣吳壹、督前部右將軍玄鄉侯臣高翔、督後部後將軍安樂亭侯臣吳班、領長史綏軍將軍臣楊儀、督左部行中監軍揚武將軍臣鄧芝、行前監軍征南將軍臣劉巴、行中護軍偏將軍臣費禕、行前護軍偏將軍漢成亭侯臣許允、行左護軍篤信中郎將臣丁咸、行右護軍偏將軍臣劉敏、行護軍征南將軍當陽亭侯臣姜維、行中典軍討虜將軍臣上官雝、行中參軍昭武中郎將臣胡濟、行參軍建議將軍臣閻晏、行參軍偏將軍臣爨習、行參軍裨將軍臣杜義、行參軍武略中郎將臣杜祺、行參軍綏戎都尉臣盛勃、領從事中郎武略中郎將臣樊岐等議，輙解平任，免官祿、節傳、印綬、符策，削其爵土。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0155-a04-040-1', 'p0155', 'sanguozhi', 'a04-040', '《三國志·蜀書十》', '劉琰字威碩，魯國人也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0155-a04-040-2', 'p0155', 'sanguozhi', 'a04-040', '《三國志·蜀書十》', '彭羕、廖立以才拔進，李嚴以幹局達，魏延以勇略任，楊儀以當官顯，劉琰舊仕，並咸貴重。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0156-a04-032-0', 'p0156', 'sanguozhi', 'a04-032', '《三國志·蜀書二》', '拔魏延為都督，鎮漢中。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0156-a04-033-1', 'p0156', 'sanguozhi', 'a04-033', '《三國志·蜀書三》', '是歲，魏延破魏雍州刺史郭淮于陽谿。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0156-a04-033-2', 'p0156', 'sanguozhi', 'a04-033', '《三國志·蜀書三》', '征西大將軍魏延與丞相長史楊儀爭權不和，舉兵相攻，延敗走；斬延首，儀率諸軍還成都。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0156-a04-035-3', 'p0156', 'sanguozhi', 'a04-035', '《三國志·蜀書五》', '郭沖三事曰：亮屯于陽平，遣魏延諸軍并兵東下，亮惟留萬人守城。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0156-a04-035-4', 'p0156', 'sanguozhi', 'a04-035', '《三國志·蜀書五》', '案魏延傳云：「延每隨亮出，輒欲請精兵萬人，與亮異道會于潼關，亮制而不許；延常謂亮為怯，歎己才用之不盡也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0156-a04-035-5', 'p0156', 'sanguozhi', 'a04-035', '《三國志·蜀書五》', '亮使魏延、高翔、吳班赴拒，大破之，獲甲首三千級、玄鎧五千領、角弩三千一百張，宣王還保營。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0156-a04-039-6', 'p0156', 'sanguozhi', 'a04-039', '《三國志·蜀書九》', '建興六年，亮出軍向祁山，時有宿將魏延、吳壹等，論者皆言以為宜令為先鋒，而亮違衆拔謖，統大衆在前，與魏將張郃戰于街亭，為郃所破，士卒離散。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0156-a04-039-7', 'p0156', 'sanguozhi', 'a04-039', '《三國志·蜀書九》', '孫權甞大醉問禕曰：「楊儀、魏延，牧豎小人也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0156-a04-040-8', 'p0156', 'sanguozhi', 'a04-040', '《三國志·蜀書十》', '輙與行中軍師車騎將軍都鄉侯臣劉琰，使持節前軍師征西大將軍領涼州刺史南鄭侯臣魏延、前將軍都亭侯臣袁綝、左將軍領荊州刺史高陽鄉侯臣吳壹、督前部右將軍玄鄉侯臣高翔、督後部後將軍安樂亭侯臣吳班、領長史綏軍將軍臣楊儀、督左部行中監軍揚武將軍臣鄧芝、行前監軍征南將軍臣劉巴、行中護軍偏將軍臣費禕、行前護軍偏將軍漢成亭侯臣許允、行左護軍篤信中郎將臣丁咸、行右護軍偏將軍臣劉敏、行護軍征南將軍當陽亭侯臣姜維、行中典軍討虜將軍臣上官雝、行中參軍昭武中郎將臣胡濟、行參軍建議將軍臣閻晏、行參軍偏將軍臣爨習、行參軍裨將軍臣杜義、行參軍武略中郎將臣杜祺、行參軍綏戎都尉臣盛勃、領從事中郎武略中郎將臣樊岐等議，輙解平任，免官祿、節傳、印綬、符策，削其爵土。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0156-a04-040-9', 'p0156', 'sanguozhi', 'a04-040', '《三國志·蜀書十》', '建興十年，與前軍師魏延不和，言語虛誕，亮責讓之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0156-a04-040-10', 'p0156', 'sanguozhi', 'a04-040', '《三國志·蜀書十》', '魏延字文長，義陽人也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0156-a04-040-11', 'p0156', 'sanguozhi', 'a04-040', '《三國志·蜀書十》', '且魏延何人，當為楊儀所部勒，作斷後將乎！');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0156-a04-040-12', 'p0156', 'sanguozhi', 'a04-040', '《三國志·蜀書十》', '亮深惜儀之才幹，憑魏延之驍勇，常恨二人之不平，不忍有所偏廢也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0156-a04-040-13', 'p0156', 'sanguozhi', 'a04-040', '《三國志·蜀書十》', '彭羕、廖立以才拔進，李嚴以幹局達，魏延以勇略任，楊儀以當官顯，劉琰舊仕，並咸貴重。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0156-a04-043-14', 'p0156', 'sanguozhi', 'a04-043', '《三國志·蜀書十三》', '十二年，亮卒於武功，軍退還，魏延作亂，一戰而敗，平之功也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0156-a04-044-15', 'p0156', 'sanguozhi', 'a04-044', '《三國志·蜀書十四》', '值軍師魏延與長史楊儀相憎惡，每至並坐爭論，延或舉刃擬儀，儀泣涕橫集。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0156-a04-044-16', 'p0156', 'sanguozhi', 'a04-044', '《三國志·蜀書十四》', '初，先主留魏延鎮漢中，皆實兵諸圍以禦外敵，敵若來攻，使不得入。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0156-a04-045-17', 'p0156', 'sanguozhi', 'a04-045', '《三國志·蜀書十五》', '建興八年，與魏延入南安界，破魏將費瑤，徙亭侯，進封高陽鄉侯，遷左將軍。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0156-a05-001-18', 'p0156', 'jinshu', 'a05-001', '《晉書·卷一》', '亮部將楊儀、魏延爭權，儀斬延，并其衆。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0157-a04-033-0', 'p0157', 'sanguozhi', 'a04-033', '《三國志·蜀書三》', '征西大將軍魏延與丞相長史楊儀爭權不和，舉兵相攻，延敗走；斬延首，儀率諸軍還成都。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0157-a04-033-1', 'p0157', 'sanguozhi', 'a04-033', '《三國志·蜀書三》', '十三年春正月，中軍師楊儀廢徙漢嘉郡。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0157-a04-035-2', 'p0157', 'sanguozhi', 'a04-035', '《三國志·蜀書五》', '」漢晉春秋曰：楊儀等整軍而出，百姓奔告宣王，宣王追焉。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0157-a04-039-3', 'p0157', 'sanguozhi', 'a04-039', '《三國志·蜀書九》', '孫權甞大醉問禕曰：「楊儀、魏延，牧豎小人也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0157-a04-040-4', 'p0157', 'sanguozhi', 'a04-040', '《三國志·蜀書十》', '輙與行中軍師車騎將軍都鄉侯臣劉琰，使持節前軍師征西大將軍領涼州刺史南鄭侯臣魏延、前將軍都亭侯臣袁綝、左將軍領荊州刺史高陽鄉侯臣吳壹、督前部右將軍玄鄉侯臣高翔、督後部後將軍安樂亭侯臣吳班、領長史綏軍將軍臣楊儀、督左部行中監軍揚武將軍臣鄧芝、行前監軍征南將軍臣劉巴、行中護軍偏將軍臣費禕、行前護軍偏將軍漢成亭侯臣許允、行左護軍篤信中郎將臣丁咸、行右護軍偏將軍臣劉敏、行護軍征南將軍當陽亭侯臣姜維、行中典軍討虜將軍臣上官雝、行中參軍昭武中郎將臣胡濟、行參軍建議將軍臣閻晏、行參軍偏將軍臣爨習、行參軍裨將軍臣杜義、行參軍武略中郎將臣杜祺、行參軍綏戎都尉臣盛勃、領從事中郎武略中郎將臣樊岐等議，輙解平任，免官祿、節傳、印綬、符策，削其爵土。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0157-a04-040-5', 'p0157', 'sanguozhi', 'a04-040', '《三國志·蜀書十》', '唯楊儀不假借延，延以為至忿，有如水火。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0157-a04-040-6', 'p0157', 'sanguozhi', 'a04-040', '《三國志·蜀書十》', '秋，亮病困，密與長史楊儀、司馬費禕、護軍姜維等作身歿之後退軍節度，令延斷後，姜維次之；若延或不從命，軍便自發。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0157-a04-040-7', 'p0157', 'sanguozhi', 'a04-040', '《三國志·蜀書十》', '且魏延何人，當為楊儀所部勒，作斷後將乎！');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0157-a04-040-8', 'p0157', 'sanguozhi', 'a04-040', '《三國志·蜀書十》', '亮長史楊儀宿與延不和，見延攝行軍事，懼為所害，乃張言延欲舉衆北附，遂率其衆攻延。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0157-a04-040-9', 'p0157', 'sanguozhi', 'a04-040', '《三國志·蜀書十》', '楊儀字威公，襄陽人也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0157-a04-040-10', 'p0157', 'sanguozhi', 'a04-040', '《三國志·蜀書十》', '彭羕、廖立以才拔進，李嚴以幹局達，魏延以勇略任，楊儀以當官顯，劉琰舊仕，並咸貴重。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0157-a04-044-11', 'p0157', 'sanguozhi', 'a04-044', '《三國志·蜀書十四》', '值軍師魏延與長史楊儀相憎惡，每至並坐爭論，延或舉刃擬儀，儀泣涕橫集。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0157-a04-045-12', 'p0157', 'sanguozhi', 'a04-045', '《三國志·蜀書十五》', '襄陽記曰：楊顒字子昭，楊儀宗人也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0157-a05-001-13', 'p0157', 'jinshu', 'a05-001', '《晉書·卷一》', '亮長史楊儀反旗鳴皷，若將距帝者。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0157-a05-001-14', 'p0157', 'jinshu', 'a05-001', '《晉書·卷一》', '帝以窮寇不之逼，於是楊儀結陣而去。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0157-a05-001-15', 'p0157', 'jinshu', 'a05-001', '《晉書·卷一》', '亮部將楊儀、魏延爭權，儀斬延，并其衆。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0158-a04-041-0', 'p0158', 'sanguozhi', 'a04-041', '《三國志·蜀書十一》', '霍峻字仲邈，南郡枝江人也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0158-a04-041-1', 'p0158', 'sanguozhi', 'a04-041', '《三國志·蜀書十一》', '評曰：霍峻孤城不傾，王連固節不移，向朗好學不倦，張裔膚敏應機，楊洪乃心忠公，費詩率意而言，皆有可紀焉。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0159-a03-088-0', 'p0159', 'houhanshu', 'a03-088', '《後漢書·卷八十八》', '其後疏勒王連相殺害，朝廷亦不能禁。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0159-a04-039-1', 'p0159', 'sanguozhi', 'a04-039', '《三國志·蜀書九》', '初，先主定益州，置鹽府校尉，較鹽鐵之利，後校尉王連請乂及南陽杜祺、南鄉劉幹等並為典曹都尉。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0159-a04-040-2', 'p0159', 'sanguozhi', 'a04-040', '《三國志·蜀書十》', '王連流俗，苟作掊克，使百姓疲弊，以致今日。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0159-a04-041-3', 'p0159', 'sanguozhi', 'a04-041', '《三國志·蜀書十一》', '王連字文儀，南陽人也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0159-a04-041-4', 'p0159', 'sanguozhi', 'a04-041', '《三國志·蜀書十一》', '後主踐阼，為步兵校尉，代王連領丞相長史。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0159-a04-041-5', 'p0159', 'sanguozhi', 'a04-041', '《三國志·蜀書十一》', '評曰：霍峻孤城不傾，王連固節不移，向朗好學不倦，張裔膚敏應機，楊洪乃心忠公，費詩率意而言，皆有可紀焉。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0160-a04-034-0', 'p0160', 'sanguozhi', 'a04-034', '《三國志·蜀書四》', '今以貴人為皇后，使行丞相事左將軍向朗持節授璽綬。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0160-a04-040-1', 'p0160', 'sanguozhi', 'a04-040', '《三國志·蜀書十》', '如向朗、文恭，凡俗之人耳。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0160-a04-041-2', 'p0160', 'sanguozhi', 'a04-041', '《三國志·蜀書十一》', '向朗字巨達，襄陽宜城人也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0160-a04-041-3', 'p0160', 'sanguozhi', 'a04-041', '《三國志·蜀書十一》', '洪對曰：「裔天姿明察，長於治劇，才誠堪之，然性不公平，恐不可專任，不如留向朗。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0160-a04-041-4', 'p0160', 'sanguozhi', 'a04-041', '《三國志·蜀書十一》', '評曰：霍峻孤城不傾，王連固節不移，向朗好學不倦，張裔膚敏應機，楊洪乃心忠公，費詩率意而言，皆有可紀焉。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0161-a04-032-0', 'p0161', 'sanguozhi', 'a04-032', '《三國志·蜀書二》', '是後在所並言衆瑞，日月相屬，故議郎陽泉侯劉豹、青衣侯向舉、偏將軍張裔 ‧ 黃權、大司馬屬殷純、益州別駕從事趙莋、治中從事楊洪、從事祭酒何宗、議曹從事杜瓊、勸學從事張爽、尹默、譙周等上言：「臣聞河圖、洛書，五經讖、緯，孔子所甄，驗應自遠。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0161-a04-033-1', 'p0161', 'sanguozhi', 'a04-033', '《三國志·蜀書三》', '先是，益州郡有大姓雍闓反，流太守張裔於吳，據郡不賔，越嶲夷王高定亦背叛。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0161-a04-041-2', 'p0161', 'sanguozhi', 'a04-041', '《三國志·蜀書十一》', '張裔字君嗣，蜀郡成都人也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0161-a04-041-3', 'p0161', 'sanguozhi', 'a04-041', '《三國志·蜀書十一》', '五年，丞相亮北住漢中，欲用張裔為留府長史，問洪何如？');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0161-a04-041-4', 'p0161', 'sanguozhi', 'a04-041', '《三國志·蜀書十一》', '評曰：霍峻孤城不傾，王連固節不移，向朗好學不倦，張裔膚敏應機，楊洪乃心忠公，費詩率意而言，皆有可紀焉。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0161-a04-043-5', 'p0161', 'sanguozhi', 'a04-043', '《三國志·蜀書十三》', '初，建寧郡殺太守正昂，縛太守張裔於吳，故都督常駐平夷縣。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0161-a04-044-6', 'p0161', 'sanguozhi', 'a04-044', '《三國志·蜀書十四》', '五年，亮住漢中，琬與長史張裔統留府事。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0161-a04-044-7', 'p0161', 'sanguozhi', 'a04-044', '《三國志·蜀書十四》', '亮與留府長史張裔、參軍蔣琬書曰：「姜伯約忠勤時事，思慮精密，考其所有，永南、季常諸人不如也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0161-a04-045-8', 'p0161', 'sanguozhi', 'a04-045', '《三國志·蜀書十五》', '恭子厷，為丞相西曹令史，隨諸葛亮於漢中，早夭，亮甚惜之，與留府長史參軍張裔、蔣琬書曰：「令史失賴厷，掾屬喪楊顒，為朝中損益多矣。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0162-a04-032-0', 'p0162', 'sanguozhi', 'a04-032', '《三國志·蜀書二》', '是後在所並言衆瑞，日月相屬，故議郎陽泉侯劉豹、青衣侯向舉、偏將軍張裔 ‧ 黃權、大司馬屬殷純、益州別駕從事趙莋、治中從事楊洪、從事祭酒何宗、議曹從事杜瓊、勸學從事張爽、尹默、譙周等上言：「臣聞河圖、洛書，五經讖、緯，孔子所甄，驗應自遠。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0162-a04-041-1', 'p0162', 'sanguozhi', 'a04-041', '《三國志·蜀書十一》', '楊洪字季休，犍為武陽人也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0162-a04-041-2', 'p0162', 'sanguozhi', 'a04-041', '《三國志·蜀書十一》', '評曰：霍峻孤城不傾，王連固節不移，向朗好學不倦，張裔膚敏應機，楊洪乃心忠公，費詩率意而言，皆有可紀焉。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0163-a04-041-0', 'p0163', 'sanguozhi', 'a04-041', '《三國志·蜀書十一》', '費詩字公舉，犍為南安人也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0163-a04-041-1', 'p0163', 'sanguozhi', 'a04-041', '《三國志·蜀書十一》', '評曰：霍峻孤城不傾，王連固節不移，向朗好學不倦，張裔膚敏應機，楊洪乃心忠公，費詩率意而言，皆有可紀焉。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0164-a04-033-0', 'p0164', 'sanguozhi', 'a04-033', '《三國志·蜀書三》', '又諸葛亮以禪立之明年領益州牧，其年與主簿杜微書曰「朝廷今年十八」，與禪傳相應，理當非虛。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0164-a04-042-1', 'p0164', 'sanguozhi', 'a04-042', '《三國志·蜀書十二》', '杜微字國輔，梓潼涪人也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0164-a04-042-2', 'p0164', 'sanguozhi', 'a04-042', '《三國志·蜀書十二》', '評曰：杜微脩身隱靜，不役當世，庶幾夷、皓之槩。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0166-a03-094-0', 'p0166', 'houhanshu', 'a03-094', '《二十四史-後漢書-志第四‧禮儀上》', '謝沈書曰：「太傅胡廣博綜舊儀，立漢制度，蔡邕依以為志，譙周後改定以為禮儀志。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0166-a03-094-1', 'p0166', 'houhanshu', 'a03-094', '《二十四史-後漢書-志第四‧禮儀上》', '譙周五經然否曰：「漢初或云三老荅天子拜，遭王莽之亂，法度殘缺。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0166-a03-094-2', 'p0166', 'houhanshu', 'a03-094', '《二十四史-後漢書-志第四‧禮儀上》', '」譙周論之曰：「禮，尸服上服，猶以非親之故荅子拜，士見異國君亦荅拜，是皆不得視猶子也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0166-a03-095-3', 'p0166', 'houhanshu', 'a03-095', '《二十四史-後漢書-志第五‧禮儀中》', '先臘一日，大儺，譙周論語注曰：「儺，却之也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0166-a03-095-4', 'p0166', 'houhanshu', 'a03-095', '《二十四史-後漢書-志第五‧禮儀中》', '」譙周論語注曰：「以葦矢射之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0166-a03-100-5', 'p0166', 'houhanshu', 'a03-100', '《二十四史-後漢書-志第十‧天文上》', '謝沈書曰：「蔡邕撰建武已後，星驗著明，以續前志，譙周接繼其下者。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0166-a03-103-6', 'p0166', 'houhanshu', 'a03-103', '《二十四史-後漢書-志第十三‧五行一》', '故泰山太守應劭、給事中董巴、散騎常侍譙周蜀志曰：「周字允南，巴西西充國人也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0166-a03-113-7', 'p0166', 'houhanshu', 'a03-113', '《二十四史-後漢書-志第二十三‧郡國五》', '譙周巴記曰：「初平元年，趙穎分巴為二郡，欲得巴舊名，故郡以墊江為治，安漢以下為永寧郡。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0166-a04-032-8', 'p0166', 'sanguozhi', 'a04-032', '《三國志·蜀書二》', '是後在所並言衆瑞，日月相屬，故議郎陽泉侯劉豹、青衣侯向舉、偏將軍張裔 ‧ 黃權、大司馬屬殷純、益州別駕從事趙莋、治中從事楊洪、從事祭酒何宗、議曹從事杜瓊、勸學從事張爽、尹默、譙周等上言：「臣聞河圖、洛書，五經讖、緯，孔子所甄，驗應自遠。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0166-a04-033-9', 'p0166', 'sanguozhi', 'a04-033', '《三國志·蜀書三》', '用光祿大夫譙周策，降於艾，奉書曰：「限分江、漢，遇值深遠，階緣蜀土，斗絕一隅，干運犯冒，漸苒歷載，遂與京畿攸隔萬里。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0166-a04-033-10', 'p0166', 'sanguozhi', 'a04-033', '《三國志·蜀書三》', '謹遣私署侍中張紹、光祿大夫譙周、駙馬都尉鄧良奉齎印緩，請命告誠，敬輸忠款，存亡勑賜，惟所裁之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0166-a04-033-11', 'p0166', 'sanguozhi', 'a04-033', '《三國志·蜀書三》', '漢晉春秋曰：後主將從譙周之策，北地王諶怒曰：「若理窮力屈，禍敗必及，便當父子君臣背城一戰，同死社稷，以見先帝可也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0166-a04-033-12', 'p0166', 'sanguozhi', 'a04-033', '《三國志·蜀書三》', '尚書令樊建、侍中張紹、光祿大夫譙周、祕書令郤正、殿中督張通並封列侯。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0166-a04-038-13', 'p0166', 'sanguozhi', 'a04-038', '《三國志·蜀書八》', '譙周蜀本紀曰：禹本汶山廣柔縣人也，生於石紐，其地名刳兒坪，見世帝紀。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0166-a04-041-14', 'p0166', 'sanguozhi', 'a04-041', '《三國志·蜀書十一》', '充聞之曰：「吾聞譙周之言，先帝諱備，其訓具也，後主諱禪，其訓授也，如言劉已具矣，當授與人也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0166-a04-042-15', 'p0166', 'sanguozhi', 'a04-042', '《三國志·蜀書十二》', '後進通儒譙周常問其意，瓊荅曰：「欲明此術甚難，須當身視，識其形色，不可信人也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0166-a04-042-16', 'p0166', 'sanguozhi', 'a04-042', '《三國志·蜀書十二》', '譙周字允南，巴西西充國人也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0166-a04-042-17', 'p0166', 'sanguozhi', 'a04-042', '《三國志·蜀書十二》', '孫綽評曰：譙周說後主降魏，可乎？');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0166-a04-042-18', 'p0166', 'sanguozhi', 'a04-042', '《三國志·蜀書十二》', '向使懷苟存之計，納譙周之言，何邦基之能構，令名之可獲哉？');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0166-a04-042-19', 'p0166', 'sanguozhi', 'a04-042', '《三國志·蜀書十二》', '景耀六年，後主從譙周之計，遣使請降於鄧艾，其書，正所造也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0166-a04-042-20', 'p0166', 'sanguozhi', 'a04-042', '《三國志·蜀書十二》', '譙周詞理淵通，為世碩儒，有董、楊之規，郤正文辭燦爛，有張、蔡之風，加其行止，君子有取焉。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0166-a04-042-21', 'p0166', 'sanguozhi', 'a04-042', '《三國志·蜀書十二》', '張璠以為譙周所陳降魏之策，蓋素料劉禪懦弱，心無害戾，故得行也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0166-a04-045-22', 'p0166', 'sanguozhi', 'a04-045', '《三國志·蜀書十五》', '又時人謂譙周無當世才，少歸敬者，唯戲重之，常稱曰：「吾等後世，終自不如此長兒也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0166-a05-011-23', 'p0166', 'jinshu', 'a05-011', '《晉書·卷十一》', '及班固敘漢史，馬遷續述天文，而蔡邕、譙周各有撰錄，司馬彪採之，以繼前志。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0166-a05-011-24', 'p0166', 'jinshu', 'a05-011', '《晉書·卷十一》', '陳卓、范蠡、鬼谷先生、張良、諸葛亮、譙周、京房、張衡並云：');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0167-a04-031-0', 'p0167', 'sanguozhi', 'a04-031', '《三國志·蜀書一》', '會益州刺史郤儉賦斂煩擾，儉，郤正祖也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0167-a04-033-1', 'p0167', 'sanguozhi', 'a04-033', '《三國志·蜀書三》', '尚書令樊建、侍中張紹、光祿大夫譙周、祕書令郤正、殿中督張通並封列侯。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0167-a04-033-2', 'p0167', 'sanguozhi', 'a04-033', '《三國志·蜀書三》', '」郤正聞之，求見禪曰：「若王後問，宜泣而荅曰『先人墳墓遠在隴、蜀，乃心西悲，無日不思』，因閉其目。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0167-a04-033-3', 'p0167', 'sanguozhi', 'a04-033', '《三國志·蜀書三》', '」會王復問，對如前，王曰：「何乃似郤正語邪！');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0167-a04-042-4', 'p0167', 'sanguozhi', 'a04-042', '《三國志·蜀書十二》', '後進文士祕書郎郤正數從光諮訪，光問正太子所習讀并其情性好尚，正荅曰：「奉親虔恭，夙夜匪懈，有古世子之風；接待羣僚，舉動出於仁恕。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0167-a04-042-5', 'p0167', 'sanguozhi', 'a04-042', '《三國志·蜀書十二》', '郤正字令先，河南偃師人也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0167-a04-042-6', 'p0167', 'sanguozhi', 'a04-042', '《三國志·蜀書十二》', '譙周詞理淵通，為世碩儒，有董、楊之規，郤正文辭燦爛，有張、蔡之風，加其行止，君子有取焉。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0167-a04-044-7', 'p0167', 'sanguozhi', 'a04-044', '《三國志·蜀書十四》', '郤正著論論維曰：「姜伯約據上將之重，處羣臣之右，宅舍弊薄，資財無餘，側室無妾媵之褻，後庭無聲樂之娛，衣服取供，輿馬取備，飲食節制，不奢不約，官給費用，隨手消盡；察其所以然者，非以激貪厲濁，抑情自割也，直謂如是為足，不在多求。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0167-a04-044-8', 'p0167', 'sanguozhi', 'a04-044', '《三國志·蜀書十四》', '臣松之以為郤正此論，取其可稱，不謂維始終行事皆可準則也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0167-a04-044-9', 'p0167', 'sanguozhi', 'a04-044', '《三國志·蜀書十四》', '餘旣過苦，又非所以難郤正也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0168-a03-075-0', 'p0168', 'houhanshu', 'a03-075', '《後漢書·卷七十五》', '」璋主簿巴西黃權諫曰：蜀志曰：「權字公衡，閬中人也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0168-a03-075-1', 'p0168', 'houhanshu', 'a03-075', '《後漢書·卷七十五》', '先主曰：『孤負黃權，權不負孤也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0168-a04-002-2', 'p0168', 'sanguozhi', 'a04-002', '《三國志·魏書二》', '八月，蜀大將黃權率衆降。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0168-a04-004-3', 'p0168', 'sanguozhi', 'a04-004', '《三國志·魏書四》', '冬十月，以鎮南將軍黃權為車騎將軍。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0168-a04-004-4', 'p0168', 'sanguozhi', 'a04-004', '《三國志·魏書四》', '夏四月，車騎將軍黃權薨。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0168-a04-004-5', 'p0168', 'sanguozhi', 'a04-004', '《三國志·魏書四》', '魏初有孟達、黃權，在晉有孫秀、孫楷；達、權爵賞比壹為輕，秀、楷禮秩優異尤甚。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0168-a04-031-6', 'p0168', 'sanguozhi', 'a04-031', '《三國志·蜀書一》', '璋主簿黃權陳其利害，從事廣漢王累自倒縣於州門以諫，璋一無所納，勑在所供奉先主，先主入境如歸。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0168-a04-032-7', 'p0168', 'sanguozhi', 'a04-032', '《三國志·蜀書二》', '及董和、黃權、李嚴等本璋之所授用也，吳壹、費觀等又璋之婚親也，彭羡又璋之所排擯也，劉巴者宿昔之所忌恨也，皆處之顯任，盡其器能。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0168-a04-032-8', 'p0168', 'sanguozhi', 'a04-032', '《三國志·蜀書二》', '遣黃權將兵迎張魯，張魯已降曹公。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0168-a04-032-9', 'p0168', 'sanguozhi', 'a04-032', '《三國志·蜀書二》', '是後在所並言衆瑞，日月相屬，故議郎陽泉侯劉豹、青衣侯向舉、偏將軍張裔 ‧ 黃權、大司馬屬殷純、益州別駕從事趙莋、治中從事楊洪、從事祭酒何宗、議曹從事杜瓊、勸學從事張爽、尹默、譙周等上言：「臣聞河圖、洛書，五經讖、緯，孔子所甄，驗應自遠。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0168-a04-032-10', 'p0168', 'sanguozhi', 'a04-032', '《三國志·蜀書二》', '鎮北將軍黃權督江北諸軍，與吳軍相拒於夷陵道。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0168-a04-037-11', 'p0168', 'sanguozhi', 'a04-037', '《三國志·蜀書七》', '統弟林，以荊州治中從事參鎮北將軍黃權征吳，值軍敗，隨權入魏，魏封列侯，至鉅鹿太守。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0168-a04-037-12', 'p0168', 'sanguozhi', 'a04-037', '《三國志·蜀書七》', '曹公之破荊州，林婦與林分隔，守養弱女十有餘年，後林隨黃權降魏，始復集聚。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0168-a04-043-13', 'p0168', 'sanguozhi', 'a04-043', '《三國志·蜀書十三》', '黃權字公衡，巴西閬中人也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0168-a04-043-14', 'p0168', 'sanguozhi', 'a04-043', '《三國志·蜀書十三》', '先主曰：「孤負黃權，權不負孤也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0168-a04-043-15', 'p0168', 'sanguozhi', 'a04-043', '《三國志·蜀書十三》', '臣松之以為漢武用虛罔之言，滅李陵之家，劉主拒憲司所執，宥黃權之室，二主得失縣邈遠矣。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0168-a04-043-16', 'p0168', 'sanguozhi', 'a04-043', '《三國志·蜀書十三》', '先主已還永安，見忠與語，謂尚書令劉巴曰：「雖亡黃權，復得狐篤，此為世不乏賢也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0168-a04-043-17', 'p0168', 'sanguozhi', 'a04-043', '《三國志·蜀書十三》', '評曰：黃權弘雅思量，李恢公亮志業，呂凱守節不回，馬忠擾而能毅，尚書曰：擾而毅。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0168-a05-013-18', 'p0168', 'jinshu', 'a05-013', '《晉書·卷十三》', '蜀記稱明帝問黃權曰：「天下鼎立，何地為正？');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0168-a05-013-19', 'p0168', 'jinshu', 'a05-013', '《晉書·卷十三》', '正始元年四月，車騎將軍黃權薨。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0169-a04-016-0', 'p0169', 'sanguozhi', 'a04-016', '《三國志·魏書十六》', '傅子曰：畿與太僕李恢、東安太守郭智有好。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0169-a04-043-1', 'p0169', 'sanguozhi', 'a04-043', '《三國志·蜀書十三》', '李恢字德昂，建寧俞元人也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0169-a04-043-2', 'p0169', 'sanguozhi', 'a04-043', '《三國志·蜀書十三》', '評曰：黃權弘雅思量，李恢公亮志業，呂凱守節不回，馬忠擾而能毅，尚書曰：擾而毅。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0169-a05-015-3', 'p0169', 'jinshu', 'a05-015', '《晉書·卷十五》', '蜀以李恢為建寧太守，遙領交州刺史。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0170-a04-043-0', 'p0170', 'sanguozhi', 'a04-043', '《三國志·蜀書十三》', '呂凱字季平、永昌不韋人也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0170-a04-043-1', 'p0170', 'sanguozhi', 'a04-043', '《三國志·蜀書十三》', '亮至南，上表曰：「永昌郡吏呂凱、府丞王伉等，執忠絕域，十有餘年，雍闓、高定偪其東北，而凱等守義不與交通。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0170-a04-043-2', 'p0170', 'sanguozhi', 'a04-043', '《三國志·蜀書十三》', '評曰：黃權弘雅思量，李恢公亮志業，呂凱守節不回，馬忠擾而能毅，尚書曰：擾而毅。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0171-a04-033-0', 'p0171', 'sanguozhi', 'a04-033', '《三國志·蜀書三》', '是歲，南夷劉胄反，將軍馬忠破平之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0171-a04-043-1', 'p0171', 'sanguozhi', 'a04-043', '《三國志·蜀書十三》', '馬忠字德信，巴西閬中人也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0171-a04-043-2', 'p0171', 'sanguozhi', 'a04-043', '《三國志·蜀書十三》', '是時，鄧芝在東，馬忠在南，平在北境，咸著名迹。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0171-a04-043-3', 'p0171', 'sanguozhi', 'a04-043', '《三國志·蜀書十三》', '拜為牙門將，屬馬忠，北討汶山叛羌，南平四郡蠻夷，輙有籌畫戰克之功。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0171-a04-043-4', 'p0171', 'sanguozhi', 'a04-043', '《三國志·蜀書十三》', '益部耆舊傳曰：嶷受兵三百人，隨馬忠討叛羌。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0171-a04-043-5', 'p0171', 'sanguozhi', 'a04-043', '《三國志·蜀書十三》', '後南夷劉胄又反，以馬忠為督庲降討胄，嶷復屬焉，戰鬬常冠軍首，遂斬胄。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0171-a04-043-6', 'p0171', 'sanguozhi', 'a04-043', '《三國志·蜀書十三》', '評曰：黃權弘雅思量，李恢公亮志業，呂凱守節不回，馬忠擾而能毅，尚書曰：擾而毅。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0171-a04-045-7', 'p0171', 'sanguozhi', 'a04-045', '《三國志·蜀書十五》', '馬忠因其成基以破殄胄，丞相亮聞而善之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0171-a04-047-8', 'p0171', 'sanguozhi', 'a04-047', '《三國志·吳書二》', '十二月，璋司馬馬忠獲羽及其子平、都督趙累等於章鄉，遂定荊州。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0171-a04-055-9', 'p0171', 'sanguozhi', 'a04-055', '《三國志·吳書十》', '璋部下司馬馬忠禽羽，并羽子平、都督趙累等。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0171-a05-006-10', 'p0171', 'jinshu', 'a05-006', '《晉書·卷六》', '十二月，劉聰故將王騰、馬忠等誅靳準，送傳國璽於劉曜。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0172-a03-017-0', 'p0172', 'houhanshu', 'a03-017', '《後漢書·卷十七》', '竊聞大王平河北，開王業，此誠皇天祐漢，士人之福也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0172-a03-018-1', 'p0172', 'houhanshu', 'a03-018', '《後漢書·卷十八》', '永平十三年，坐與舅王平謀反，伏誅，國除。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0172-a03-027-2', 'p0172', 'houhanshu', 'a03-027', '《後漢書·卷二十七》', '」武王平殷亂，而二人恥之，義不食周粟，餓死於首陽山。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0172-a03-041-3', 'p0172', 'houhanshu', 'a03-041', '《後漢書·卷四十一》', '與三府掾屬共考案楚獄顏忠、王平等，辭連及隧鄉侯耿建、朗陵侯臧信、護澤侯鄧鯉、曲成侯劉建。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0172-a03-042-4', 'p0172', 'houhanshu', 'a03-042', '《後漢書·卷四十二》', '十三年，男子燕廣告英與漁陽王平、顏忠等造作圖書，有逆謀，事下案驗。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0172-a04-030-5', 'p0172', 'sanguozhi', 'a04-030', '《三國志·魏書三十》', '王有五宮，一宮間相去十里，其王平旦之一宮聽事，至日暮一宿，明日復至一宮，五日一周。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0172-a04-033-6', 'p0172', 'sanguozhi', 'a04-033', '《三國志·蜀書三》', '七年閏月，魏大將軍曹爽、夏侯玄等向漢中，鎮北大將軍王平拒興勢圍，大將軍費禕督諸軍往赴救，魏軍退。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0172-a04-043-7', 'p0172', 'sanguozhi', 'a04-043', '《三國志·蜀書十三》', '王平字子均，巴西宕渠人也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0172-a04-043-8', 'p0172', 'sanguozhi', 'a04-043', '《三國志·蜀書十三》', '王平忠勇而嚴整，張嶷識斷明果，咸以所長，顯名發迹，遇其時也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0172-a04-044-9', 'p0172', 'sanguozhi', 'a04-044', '《三國志·蜀書十四》', '劉敏，左護軍、揚威將軍，與鎮北大將軍王平俱鎮漢中。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0172-a04-044-10', 'p0172', 'sanguozhi', 'a04-044', '《三國志·蜀書十四》', '及興勢之役，王平捍拒曹爽，皆承此制。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0173-a04-028-0', 'p0173', 'sanguozhi', 'a04-028', '《三國志·魏書二十八》', '未到，聞其已破，退趣白水，與蜀將張翼、廖化等合守劒閣拒會。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0173-a04-028-1', 'p0173', 'sanguozhi', 'a04-028', '《三國志·魏書二十八》', '會上言曰：「賊姜維、張翼、廖化、董厥等逃死遁走，欲趣成都。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0173-a04-033-2', 'p0173', 'sanguozhi', 'a04-033', '《三國志·蜀書三》', '於是遣左右車騎將軍張翼、廖化、輔國大將軍董厥等拒之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0173-a04-036-3', 'p0173', 'sanguozhi', 'a04-036', '《三國志·蜀書六》', '公軍追至圍，此時沔陽長張翼在雲圍內，翼欲閉門拒守，而雲入營，更大開門，偃旗息鼓。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0173-a04-043-4', 'p0173', 'sanguozhi', 'a04-043', '《三國志·蜀書十三》', '徵庲降都督張翼還，以忠代翼。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0173-a04-043-5', 'p0173', 'sanguozhi', 'a04-043', '《三國志·蜀書十三》', '華陽國志曰：後張翼、廖化並為大將軍，時人語曰：「前有王、句，後有張、廖。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0173-a04-044-6', 'p0173', 'sanguozhi', 'a04-044', '《三國志·蜀書十四》', '六年，維表後主：「聞鍾會治兵關中，欲規進取，宜並遣張翼、廖化督諸軍分護陽安關口、陰平橋頭以防未然。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0173-a04-044-7', 'p0173', 'sanguozhi', 'a04-044', '《三國志·蜀書十四》', '及鍾會將向駱谷，鄧艾將入沓中，然後乃遣右車騎廖化詣沓中為維援，左車騎張翼、輔國大將軍董厥等詣陽安關口以為諸圍外助。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0173-a04-045-8', 'p0173', 'sanguozhi', 'a04-045', '《三國志·蜀書十五》', '張翼字伯恭，犍為武陽人也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0173-a04-045-9', 'p0173', 'sanguozhi', 'a04-045', '《三國志·蜀書十五》', '官位與張翼齊，而在宗預之右。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0173-a04-045-10', 'p0173', 'sanguozhi', 'a04-045', '《三國志·蜀書十五》', '評曰：鄧芝堅貞簡亮，臨官忘家，張翼亢姜維之銳，宗預禦孫權之嚴，咸有可稱。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0173-a05-002-11', 'p0173', 'jinshu', 'a05-002', '《晉書·卷二》', '維與張翼、廖化合軍守劔閣，鍾會攻之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0174-a04-033-0', 'p0174', 'sanguozhi', 'a04-033', '《三國志·蜀書三》', '以丞相留府長史蔣琬為尚書令，總統國事。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0174-a04-033-1', 'p0174', 'sanguozhi', 'a04-033', '《三國志·蜀書三》', '夏四月，進蔣琬位為大將軍。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0174-a04-033-2', 'p0174', 'sanguozhi', 'a04-033', '《三國志·蜀書三》', '冬十一月，大將軍蔣琬出屯漢中。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0174-a04-033-3', 'p0174', 'sanguozhi', 'a04-033', '《三國志·蜀書三》', '二年春三月，進蔣琬位為大司馬。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0174-a04-033-4', 'p0174', 'sanguozhi', 'a04-033', '《三國志·蜀書三》', '四年冬十月，尚書令費禕至漢中，與蔣琬諮論事計，歲盡還。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0174-a04-033-5', 'p0174', 'sanguozhi', 'a04-033', '《三國志·蜀書三》', '六年冬十月，大司馬蔣琬自漢中還，住涪。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0174-a04-033-6', 'p0174', 'sanguozhi', 'a04-033', '《三國志·蜀書三》', '冬十一月，大司馬蔣琬卒。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0174-a04-036-7', 'p0174', 'sanguozhi', 'a04-036', '《三國志·蜀書六》', '初，先主時，惟法正見謚；後主時，諸葛亮功德蓋世，蔣琬、費禕荷國之重，亦見謚；陳祗寵待，特加殊獎，夏侯霸遠來歸國，故復得謚；於是關羽、張飛、馬超、龐統、黃忠及雲乃追謚，時論以為榮。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0174-a04-039-8', 'p0174', 'sanguozhi', 'a04-039', '《三國志·蜀書九》', '蔣琬後詣漢中，謂亮曰：「昔楚殺得臣，然後文公喜可知也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0174-a04-039-9', 'p0174', 'sanguozhi', 'a04-039', '《三國志·蜀書九》', '九年，都護李平坐誣罔廢；諸葛亮與長史蔣琬、侍中董允書曰：「孝起前臨至吳，為吾說正方腹中有鱗甲，鄉黨以為不可近。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0174-a04-039-10', 'p0174', 'sanguozhi', 'a04-039', '《三國志·蜀書九》', '尚書令蔣琬領益州刺史，上疏以讓費禕及允，又表「允內侍歷年，翼贊王室，宜賜爵土以襃勳勞。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0174-a04-039-11', 'p0174', 'sanguozhi', 'a04-039', '《三國志·蜀書九》', '華陽國志曰：時蜀人以諸葛亮、蔣琬、費禕及允為四相，一號四英也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0174-a04-040-12', 'p0174', 'sanguozhi', 'a04-040', '《三國志·蜀書十》', '後丞相掾李邵、蔣琬至，立計曰：「軍當遠出，卿諸人好諦其事。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0174-a04-040-13', 'p0174', 'sanguozhi', 'a04-040', '《三國志·蜀書十》', '後主以問侍中董允、留府長史蔣琬，琬、允咸保儀疑延。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0174-a04-040-14', 'p0174', 'sanguozhi', 'a04-040', '《三國志·蜀書十》', '初，蔣琬率宿衞諸營赴難北行，行數十里，延死問至，乃旋。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0174-a04-040-15', 'p0174', 'sanguozhi', 'a04-040', '《三國志·蜀書十》', '而亮平生宓指，以儀性狷狹，意在蔣琬，琬遂為尚書令、益州刺史。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0174-a04-041-16', 'p0174', 'sanguozhi', 'a04-041', '《三國志·蜀書十一》', '建興三年，隨諸葛亮南行，歸至漢陽縣，降人李鴻來詣亮，亮見鴻，時蔣琬與詩在坐。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0174-a04-041-17', 'p0174', 'sanguozhi', 'a04-041', '《三國志·蜀書十一》', '蔣琬秉政，以詩為諫議大夫，卒於家。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0174-a04-042-18', 'p0174', 'sanguozhi', 'a04-042', '《三國志·蜀書十二》', '蔣琬、費禕等皆器重之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0174-a04-042-19', 'p0174', 'sanguozhi', 'a04-042', '《三國志·蜀書十二》', '大將軍蔣琬領刺史，徙為典學從事，緫州之學者。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0174-a04-042-20', 'p0174', 'sanguozhi', 'a04-042', '《三國志·蜀書十二》', '立上言：「故蜀大官及盡忠死事者子孫，雖仕郡國，或有不才，同之齊民為劇；又諸葛亮、蔣琬、費禕等子孫流徙中畿，各宜量才叙用，以慰巴、蜀之心，傾吳人之望。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0174-a04-043-21', 'p0174', 'sanguozhi', 'a04-043', '《三國志·蜀書十三》', '八年，召為丞相參軍，副長史蔣琬署留府事。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0174-a04-043-22', 'p0174', 'sanguozhi', 'a04-043', '《三國志·蜀書十三》', '延熈五年還朝，因至漢中，見大司馬蔣琬，宣傳詔旨，加拜鎮南大將軍。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0174-a04-043-23', 'p0174', 'sanguozhi', 'a04-043', '《三國志·蜀書十三》', '延熈元年，大將軍蔣琬住沔陽，平更為前護軍，署琬府事。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0174-a04-043-24', 'p0174', 'sanguozhi', 'a04-043', '《三國志·蜀書十三》', '十四年，武都氐王符健請降，遣將軍張尉往迎，過期不到，大將軍蔣琬深以為念。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0174-a04-044-25', 'p0174', 'sanguozhi', 'a04-044', '《三國志·蜀書十四》', '蔣琬字公琰、零陵湘鄉人也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0174-a04-044-26', 'p0174', 'sanguozhi', 'a04-044', '《三國志·蜀書十四》', '軍師將軍諸葛亮請曰：「蔣琬，社稷之器，非百里之才也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0174-a04-044-27', 'p0174', 'sanguozhi', 'a04-044', '《三國志·蜀書十四》', '頃之，代蔣琬為尚書令。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0174-a04-044-28', 'p0174', 'sanguozhi', 'a04-044', '《三國志·蜀書十四》', '亮與留府長史張裔、參軍蔣琬書曰：「姜伯約忠勤時事，思慮精密，考其所有，永南、季常諸人不如也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0174-a04-044-29', 'p0174', 'sanguozhi', 'a04-044', '《三國志·蜀書十四》', '延熈元年，隨大將軍蔣琬住漢中。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0174-a04-044-30', 'p0174', 'sanguozhi', 'a04-044', '《三國志·蜀書十四》', '評曰：蔣琬方整有威重，費禕寬濟而博愛，咸承諸葛之成規，因循而不革，是以邊境無虞，邦家和一，然猶未盡治小之宜，居靜之理也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0174-a04-045-31', 'p0174', 'sanguozhi', 'a04-045', '《三國志·蜀書十五》', '亮卒，為尚書右選部郎，刺史蔣琬請為治中從事史。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0174-a04-045-32', 'p0174', 'sanguozhi', 'a04-045', '《三國志·蜀書十五》', '恭子厷，為丞相西曹令史，隨諸葛亮於漢中，早夭，亮甚惜之，與留府長史參軍張裔、蔣琬書曰：「令史失賴厷，掾屬喪楊顒，為朝中損益多矣。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0174-a04-045-33', 'p0174', 'sanguozhi', 'a04-045', '《三國志·蜀書十五》', '後大將軍蔣琬問張休曰：「漢嘉前輩有王元泰，今誰繼者？');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0174-a04-045-34', 'p0174', 'sanguozhi', 'a04-045', '《三國志·蜀書十五》', '延熈初，大將軍蔣琬出征漢中，福以前監軍領司馬，卒。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0174-a04-045-35', 'p0174', 'sanguozhi', 'a04-045', '《三國志·蜀書十五》', '乞復請，蔣琬之後，誰可任者？');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0174-a04-047-36', 'p0174', 'sanguozhi', 'a04-047', '《三國志·吳書二》', '又蔣琬守漢中，聞司馬懿南向，不出兵乘虛以掎角之，反委漢中，還近成都。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0174-a04-061-37', 'p0174', 'sanguozhi', 'a04-061', '《三國志·吳書十六》', '江表傳曰：時濬姨兄零陵蔣琬為蜀大將軍，或有間濬於武陵太守衞旌者，云濬遣密使與琬相聞，欲有自託之計。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0175-a04-004-0', 'p0175', 'sanguozhi', 'a04-004', '《三國志·魏書四》', '往歲偽大將軍費禕驅率羣衆，陰圖闚𨵦，道經漢壽，請會衆賔，脩於廣坐之中手刃擊禕，勇過聶政，功逾介子，可謂殺身成仁，釋生取義者矣。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0175-a04-004-1', 'p0175', 'sanguozhi', 'a04-004', '《三國志·魏書四》', '魏之與蜀，雖為敵國，非有趙襄滅智之仇，燕丹危亡之急；且劉禪凡下之主，費禕中才之相，二人存亡，固無關於興喪。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0175-a04-009-2', 'p0175', 'sanguozhi', 'a04-009', '《三國志·魏書九》', '費禕進兵據三嶺以截爽，爽爭嶮苦戰，僅乃得過。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0175-a04-033-3', 'p0175', 'sanguozhi', 'a04-033', '《三國志·蜀書三》', '四年冬十月，尚書令費禕至漢中，與蔣琬諮論事計，歲盡還。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0175-a04-033-4', 'p0175', 'sanguozhi', 'a04-033', '《三國志·蜀書三》', '以尚書令費禕為大將軍。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0175-a04-033-5', 'p0175', 'sanguozhi', 'a04-033', '《三國志·蜀書三》', '七年閏月，魏大將軍曹爽、夏侯玄等向漢中，鎮北大將軍王平拒興勢圍，大將軍費禕督諸軍往赴救，魏軍退。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0175-a04-033-6', 'p0175', 'sanguozhi', 'a04-033', '《三國志·蜀書三》', '十二月，大將軍費禕至漢中，行圍守。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0175-a04-033-7', 'p0175', 'sanguozhi', 'a04-033', '《三國志·蜀書三》', '九年夏六月，費禕還成都。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0175-a04-033-8', 'p0175', 'sanguozhi', 'a04-033', '《三國志·蜀書三》', '十一年夏五月，大將軍費禕出屯漢中。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0175-a04-033-9', 'p0175', 'sanguozhi', 'a04-033', '《三國志·蜀書三》', '十四年夏，大將軍費禕還成都。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0175-a04-033-10', 'p0175', 'sanguozhi', 'a04-033', '《三國志·蜀書三》', '十六年春正月，大將軍費禕為魏降人郭循所殺于漢壽。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0175-a04-035-11', 'p0175', 'sanguozhi', 'a04-035', '《三國志·蜀書五》', '侍中、侍郎郭攸之、費禕、董允等，此皆良實，志慮忠純，是以先帝簡拔以遺陛下。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0175-a04-036-12', 'p0175', 'sanguozhi', 'a04-036', '《三國志·蜀書六》', '初，先主時，惟法正見謚；後主時，諸葛亮功德蓋世，蔣琬、費禕荷國之重，亦見謚；陳祗寵待，特加殊獎，夏侯霸遠來歸國，故復得謚；於是關羽、張飛、馬超、龐統、黃忠及雲乃追謚，時論以為榮。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0175-a04-039-13', 'p0175', 'sanguozhi', 'a04-039', '《三國志·蜀書九》', '上疏曰：「侍中郭攸之 ‧ 費禕、侍郎董允等，先帝簡拔以遺陛下，至於斟酌規益，進盡忠言，則其任也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0175-a04-039-14', 'p0175', 'sanguozhi', 'a04-039', '《三國志·蜀書九》', '尚書令蔣琬領益州刺史，上疏以讓費禕及允，又表「允內侍歷年，翼贊王室，宜賜爵土以襃勳勞。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0175-a04-039-15', 'p0175', 'sanguozhi', 'a04-039', '《三國志·蜀書九》', '允甞與尚書令費禕、中典軍胡濟等共期游宴，嚴駕已辦，而郎中襄陽董恢詣允脩敬。');
